class Device(BaseModel):
    # ESP32 identity
    chip_mac: str

    # Legacy compatibility value.
    # The backend will verify it against the selected profile.
    node_type: str

    # Stable sensor-profile identity
    profile_id: int | None = None
    profile_code: str | None = None
    profile_version: int | None = None

    # Payload contract selected by the profile
    payload_version: int | None = None
    payload_encoder_key: str | None = None
    uplink_interval_seconds: int | None = None

    # Firmware reporting
    firmware_version: str | None = None

    # Location information
    building: str
    floor: str
    room: str
    room_id: int | None = None

    # Installer metadata
    label: str | None = None
    x: int | None = None
    y: int | None = None
    icon_type: str | None = None

    # Legacy compatibility; canonical capabilities come from profile
    capabilities: list[str] | None = None


