def profile_json_load(value, default):
    """
    Safely convert a JSON database value into a Python value.
    """

    if value is None:
        return default

    if isinstance(value, (dict, list, int, float, bool)):
        return value

    try:
        return json.loads(value)
    except Exception:
        return default


def profile_unique_string_list(values):
    """
    Return a clean list of unique, lowercase string values.
    """

    result = []
    seen = set()

    for value in values or []:
        clean_value = str(value).strip().lower()

        if not clean_value:
            continue

        if clean_value in seen:
            continue

        seen.add(clean_value)
        result.append(clean_value)

    return result


def profile_value_to_boolean(value, default=False):
    """
    Convert common JSON, HTML and database values into a Boolean.
    """

    if value is None:
        return default

    if isinstance(value, bool):
        return value

    if isinstance(value, (int, float)):
        return value != 0

    return str(value).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
        "enabled",
    }


def profile_optional_integer(value, field_name, errors, minimum=None, maximum=None):
    """
    Validate and normalize an optional integer.
    """

    if value is None or value == "":
        return None

    try:
        result = int(value)
    except Exception:
        errors.append(f"{field_name} must be an integer")
        return None

    if minimum is not None and result < minimum:
        errors.append(
            f"{field_name} must be greater than or equal to {minimum}"
        )

    if maximum is not None and result > maximum:
        errors.append(
            f"{field_name} must be less than or equal to {maximum}"
        )

    return result


def profile_optional_float(value, field_name, errors):
    """
    Validate and normalize an optional numeric value.
    """

    if value is None or value == "":
        return None

    try:
        return float(value)
    except Exception:
        errors.append(f"{field_name} must be numeric")
        return None


def calculate_sensor_profile_checksum(profile_definition: dict) -> str:
    """
    Create a deterministic checksum for a complete profile definition.
    """

    checksum_payload = {
        "profile_code": profile_definition.get("profile_code"),
        "profile_name": profile_definition.get("profile_name"),
        "profile_version": profile_definition.get("profile_version"),
        "node_type": profile_definition.get("node_type"),
        "description": profile_definition.get("description"),
        "capabilities": profile_definition.get("capabilities", []),
        "configuration_schema": profile_definition.get(
            "configuration_schema",
            {},
        ),
        "payload_encoder_key": profile_definition.get(
            "payload_encoder_key"
        ),
        "payload_version": profile_definition.get("payload_version"),
        "f_port": profile_definition.get("f_port"),
        "uplink_interval_seconds": profile_definition.get(
            "uplink_interval_seconds"
        ),
        "ttn_formatter_code": profile_definition.get(
            "ttn_formatter_code"
        ),
        "ttn_formatter_type": profile_definition.get(
            "ttn_formatter_type"
        ),
        "tb_device_profile_name": profile_definition.get(
            "tb_device_profile_name"
        ),
        "icon_type": profile_definition.get("icon_type"),
        "icon_color": profile_definition.get("icon_color"),
        "fields": profile_definition.get("fields", []),
        "rules": profile_definition.get("rules", []),
        "sensors": profile_definition.get("sensors", []),
    }

    canonical_json = json.dumps(
        checksum_payload,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )

    return hashlib.sha256(
        canonical_json.encode("utf-8")
    ).hexdigest()


def list_sensor_profile_summaries(
    conn: sqlite3.Connection,
    include_disabled: bool = True,
):
    """
    Return lightweight profile records for dropdowns and list pages.
    """

    sql = """
        SELECT
            p.id,
            p.profile_code,
            p.profile_name,
            p.profile_version,
            p.node_type,
            p.description,
            p.capabilities_json,
            p.payload_encoder_key,
            p.payload_version,
            p.f_port,
            p.uplink_interval_seconds,
            p.tb_device_profile_name,
            p.icon_type,
            p.icon_color,
            p.status,
            p.enabled,
            p.is_system,
            p.schema_checksum,
            p.created_at,
            p.updated_at,

            (
                SELECT COUNT(*)
                FROM sensor_profile_fields f
                WHERE f.profile_id = p.id
            ) AS field_count,

            (
                SELECT COUNT(*)
                FROM sensor_profile_rules r
                WHERE r.profile_id = p.id
            ) AS rule_count,

            (
                SELECT COUNT(*)
                FROM sensor_profile_sensors s
                WHERE s.profile_id = p.id
            ) AS sensor_count,

            (
                SELECT COUNT(*)
                FROM devices d
                WHERE d.profile_id = p.id
                   OR (
                        d.profile_id IS NULL
                        AND d.profile_code = p.profile_code
                   )
            ) AS device_count

        FROM sensor_profiles p
    """

    parameters = []

    if not include_disabled:
        sql += """
            WHERE p.enabled = 1
              AND p.status = 'active'
        """

    sql += """
        ORDER BY
            CASE p.status
                WHEN 'active' THEN 1
                WHEN 'draft' THEN 2
                WHEN 'deprecated' THEN 3
                WHEN 'archived' THEN 4
                ELSE 5
            END,
            p.profile_name,
            p.profile_version DESC
    """

    rows = conn.execute(sql, parameters).fetchall()

    result = []

    for row in rows:
        profile = dict(row)

        profile["capabilities"] = profile_json_load(
            profile.pop("capabilities_json", None),
            [],
        )

        profile["enabled"] = bool(profile.get("enabled"))
        profile["is_system"] = bool(profile.get("is_system"))

        profile["can_delete"] = (
            not profile["is_system"]
            and int(profile.get("device_count") or 0) == 0
        )

        result.append(profile)

    return result


def get_sensor_profile_row(
    conn: sqlite3.Connection,
    profile_identifier,
):
    """
    Find a profile using either its numeric ID or profile code.
    """

    if profile_identifier is None:
        return None

    if isinstance(profile_identifier, int):
        return conn.execute(
            """
            SELECT *
            FROM sensor_profiles
            WHERE id = ?
            LIMIT 1
            """,
            (profile_identifier,),
        ).fetchone()

    clean_identifier = str(profile_identifier).strip()

    if clean_identifier.isdigit():
        return conn.execute(
            """
            SELECT *
            FROM sensor_profiles
            WHERE id = ?
            LIMIT 1
            """,
            (int(clean_identifier),),
        ).fetchone()

    return conn.execute(
        """
        SELECT *
        FROM sensor_profiles
        WHERE UPPER(profile_code) = UPPER(?)
        LIMIT 1
        """,
        (clean_identifier,),
    ).fetchone()


def get_sensor_profile_detail(
    conn: sqlite3.Connection,
    profile_identifier,
    include_formatter: bool = True,
):
    """
    Return one complete profile with fields, rules, sensors,
    compatibility information and usage information.
    """

    profile_row = get_sensor_profile_row(
        conn,
        profile_identifier,
    )

    if not profile_row:
        return None

    profile = dict(profile_row)

    profile["capabilities"] = profile_json_load(
        profile.pop("capabilities_json", None),
        [],
    )

    profile["configuration_schema"] = profile_json_load(
        profile.pop("configuration_schema_json", None),
        {},
    )

    profile["enabled"] = bool(profile.get("enabled"))
    profile["is_system"] = bool(profile.get("is_system"))

    if not include_formatter:
        profile.pop("ttn_formatter_code", None)

    # ---------------------------------------------------------
    # Telemetry fields
    # ---------------------------------------------------------

    field_rows = conn.execute(
        """
        SELECT *
        FROM sensor_profile_fields
        WHERE profile_id = ?
        ORDER BY display_order, payload_order, id
        """,
        (profile["id"],),
    ).fetchall()

    fields = []

    for row in field_rows:
        field = dict(row)

        field["required"] = bool(field.get("required"))
        field["nullable"] = bool(field.get("nullable"))
        field["signed"] = bool(field.get("signed"))
        field["visible_floor"] = bool(
            field.get("visible_floor")
        )
        field["visible_dashboard"] = bool(
            field.get("visible_dashboard")
        )

        field["default_value"] = profile_json_load(
            field.pop("default_value_json", None),
            None,
        )

        fields.append(field)

    profile["fields"] = fields

    # ---------------------------------------------------------
    # Alarm rules
    # ---------------------------------------------------------

    rule_rows = conn.execute(
        """
        SELECT *
        FROM sensor_profile_rules
        WHERE profile_id = ?
        ORDER BY
            CASE severity
                WHEN 'critical' THEN 1
                WHEN 'warning' THEN 2
                WHEN 'info' THEN 3
                ELSE 4
            END,
            id
        """,
        (profile["id"],),
    ).fetchall()

    rules = []

    for row in rule_rows:
        rule = dict(row)

        rule["enabled"] = bool(rule.get("enabled"))
        rule["auto_resolve"] = bool(
            rule.get("auto_resolve")
        )

        if rule.get("expected_boolean") is not None:
            rule["expected_boolean"] = bool(
                rule["expected_boolean"]
            )

        rules.append(rule)

    profile["rules"] = rules

    # ---------------------------------------------------------
    # Physical sensors and firmware modules
    # ---------------------------------------------------------

    sensor_rows = conn.execute(
        """
        SELECT
            relation.id AS relation_id,
            relation.role,
            relation.required,
            relation.configuration_json,
            relation.display_order,

            catalog.id AS sensor_id,
            catalog.sensor_code,
            catalog.manufacturer,
            catalog.model,
            catalog.use_case,
            catalog.protocol AS sensor_protocol,
            catalog.default_bus,
            catalog.default_address,
            catalog.datasheet_url,
            catalog.description AS sensor_description,
            catalog.enabled AS sensor_enabled,

            module.id AS firmware_module_id,
            module.module_key,
            module.display_name AS module_display_name,
            module.driver_class,
            module.protocol AS module_protocol,
            module.library_name,
            module.library_version,
            module.supported_board,
            module.min_firmware_version,
            module.source_file,
            module.notes AS module_notes,
            module.enabled AS module_enabled

        FROM sensor_profile_sensors relation

        INNER JOIN sensor_catalog catalog
            ON catalog.id = relation.sensor_id

        LEFT JOIN firmware_modules module
            ON module.id = relation.firmware_module_id

        WHERE relation.profile_id = ?

        ORDER BY relation.display_order, relation.id
        """,
        (profile["id"],),
    ).fetchall()

    sensors = []

    for row in sensor_rows:
        sensor = dict(row)

        sensor["required"] = bool(sensor.get("required"))
        sensor["sensor_enabled"] = bool(
            sensor.get("sensor_enabled")
        )

        if sensor.get("module_enabled") is not None:
            sensor["module_enabled"] = bool(
                sensor["module_enabled"]
            )

        sensor["configuration"] = profile_json_load(
            sensor.pop("configuration_json", None),
            {},
        )

        sensors.append(sensor)

    profile["sensors"] = sensors

    # ---------------------------------------------------------
    # Firmware compatibility
    # ---------------------------------------------------------

    compatibility_rows = conn.execute(
        """
        SELECT
            compatibility.id,
            compatibility.profile_id,
            compatibility.firmware_module_id,
            compatibility.min_firmware_version,
            compatibility.max_firmware_version,
            compatibility.hardware_revision,
            compatibility.required_features_json,
            compatibility.enabled,

            module.module_key,
            module.display_name,
            module.driver_class,
            module.supported_board

        FROM profile_firmware_compatibility compatibility

        INNER JOIN firmware_modules module
            ON module.id = compatibility.firmware_module_id

        WHERE compatibility.profile_id = ?

        ORDER BY module.display_name
        """,
        (profile["id"],),
    ).fetchall()

    compatibility = []

    for row in compatibility_rows:
        item = dict(row)

        item["enabled"] = bool(item.get("enabled"))

        item["required_features"] = profile_json_load(
            item.pop("required_features_json", None),
            [],
        )

        compatibility.append(item)

    profile["firmware_compatibility"] = compatibility

    # ---------------------------------------------------------
    # Version history summary
    # ---------------------------------------------------------

    version_rows = conn.execute(
        """
        SELECT
            id,
            version,
            change_note,
            created_by,
            created_at
        FROM sensor_profile_versions
        WHERE profile_id = ?
        ORDER BY version DESC
        """,
        (profile["id"],),
    ).fetchall()

    profile["versions"] = [
        dict(row)
        for row in version_rows
    ]

    # ---------------------------------------------------------
    # Device usage
    # ---------------------------------------------------------

    device_rows = conn.execute(
        """
        SELECT
            device_id,
            chip_mac,
            label,
            node_type,
            building,
            floor,
            room,
            profile_code,
            profile_version,
            configuration_status,
            configuration_error
        FROM devices
        WHERE profile_id = ?
           OR (
                profile_id IS NULL
                AND profile_code = ?
           )
        ORDER BY label, device_id
        """,
        (
            profile["id"],
            profile["profile_code"],
        ),
    ).fetchall()

    profile["assigned_devices"] = [
        dict(row)
        for row in device_rows
    ]

    profile["device_count"] = len(
        profile["assigned_devices"]
    )

    profile["can_delete"] = (
        not profile["is_system"]
        and profile["device_count"] == 0
    )

    return profile

def firmware_version_tuple(value: str | None):
    """
    Convert a semantic firmware version such as 1.0.0 into a tuple
    that can be safely compared.

    Pre-release text after a dash is ignored:
        1.2.0-beta -> (1, 2, 0)
    """

    clean_value = str(value or "").strip()

    if not clean_value:
        return None

    clean_value = clean_value.split("-", 1)[0]

    parts = clean_value.split(".")

    if not 1 <= len(parts) <= 4:
        return None

    normalized_parts = []

    for part in parts:
        if not part.isdigit():
            return None

        normalized_parts.append(int(part))

    while len(normalized_parts) < 4:
        normalized_parts.append(0)

    return tuple(normalized_parts)


def firmware_version_is_compatible(
    current_version: str,
    minimum_version: str | None,
    maximum_version: str | None,
):
    """
    Check whether one firmware version falls within an optional
    inclusive minimum and maximum range.
    """

    current_tuple = firmware_version_tuple(current_version)

    if current_tuple is None:
        return False

    if minimum_version:
        minimum_tuple = firmware_version_tuple(minimum_version)

        if minimum_tuple is None:
            return False

        if current_tuple < minimum_tuple:
            return False

    if maximum_version:
        maximum_tuple = firmware_version_tuple(maximum_version)

        if maximum_tuple is None:
            return False

        if current_tuple > maximum_tuple:
            return False

    return True

def resolve_sensor_profile_for_provision(
    conn: sqlite3.Connection,
    device: Device,
):
    """
    Validate the LILYGO profile selection against the database and
    return backend-controlled canonical values.

    Browser-submitted values are never treated as the source of truth.
    """

    # ---------------------------------------------------------
    # 1. Require profile identity
    # ---------------------------------------------------------

    if device.profile_id is None:
        raise HTTPException(
            status_code=400,
            detail="profile_id is required for profile-driven provisioning",
        )

    submitted_profile_code = str(
        device.profile_code or ""
    ).strip().upper()

    if not submitted_profile_code:
        raise HTTPException(
            status_code=400,
            detail="profile_code is required for profile-driven provisioning",
        )

    # ---------------------------------------------------------
    # 2. Load profile using its stable database ID
    # ---------------------------------------------------------

    profile_row = get_sensor_profile_row(
        conn,
        device.profile_id,
    )

    if not profile_row:
        raise HTTPException(
            status_code=404,
            detail=f"Sensor profile not found: {device.profile_id}",
        )

    profile = dict(profile_row)

    stored_profile_code = str(
        profile.get("profile_code") or ""
    ).strip().upper()

    # ---------------------------------------------------------
    # 3. Verify ID and code belong to the same profile
    # ---------------------------------------------------------

    if submitted_profile_code != stored_profile_code:
        raise HTTPException(
            status_code=409,
            detail={
                "message": "profile_id and profile_code do not match",
                "submitted_profile_id": device.profile_id,
                "submitted_profile_code": submitted_profile_code,
                "stored_profile_code": stored_profile_code,
            },
        )

    # ---------------------------------------------------------
    # 4. Only active and enabled profiles can be provisioned
    # ---------------------------------------------------------

    if not bool(profile.get("enabled")):
        raise HTTPException(
            status_code=409,
            detail=f"Sensor profile is disabled: {stored_profile_code}",
        )

    if str(profile.get("status") or "").strip().lower() != "active":
        raise HTTPException(
            status_code=409,
            detail=(
                "Sensor profile must be active before provisioning: "
                f"{stored_profile_code}"
            ),
        )

    # ---------------------------------------------------------
    # 5. Verify submitted profile and payload versions
    # ---------------------------------------------------------

    stored_profile_version = int(
        profile.get("profile_version") or 0
    )

    stored_payload_version = int(
        profile.get("payload_version") or 0
    )

    if device.profile_version != stored_profile_version:
        raise HTTPException(
            status_code=409,
            detail={
                "message": "Profile version is outdated or invalid",
                "submitted": device.profile_version,
                "current": stored_profile_version,
            },
        )

    if device.payload_version != stored_payload_version:
        raise HTTPException(
            status_code=409,
            detail={
                "message": "Payload version does not match the profile",
                "submitted": device.payload_version,
                "current": stored_payload_version,
            },
        )

    # ---------------------------------------------------------
    # 6. Verify encoder and transmission interval
    # ---------------------------------------------------------

    stored_encoder_key = str(
        profile.get("payload_encoder_key") or ""
    ).strip()

    submitted_encoder_key = str(
        device.payload_encoder_key or ""
    ).strip()

    if submitted_encoder_key != stored_encoder_key:
        raise HTTPException(
            status_code=409,
            detail={
                "message": "Payload encoder does not match the profile",
                "submitted": submitted_encoder_key,
                "current": stored_encoder_key,
            },
        )

    stored_interval = int(
        profile.get("uplink_interval_seconds") or 0
    )

    if device.uplink_interval_seconds != stored_interval:
        raise HTTPException(
            status_code=409,
            detail={
                "message": (
                    "Uplink interval does not match the selected profile"
                ),
                "submitted": device.uplink_interval_seconds,
                "current": stored_interval,
            },
        )

    # ---------------------------------------------------------
    # 7. Verify node type
    # ---------------------------------------------------------

    stored_node_type = str(
        profile.get("node_type") or ""
    ).strip().lower()

    submitted_node_type = str(
        device.node_type or ""
    ).strip().lower()

    if submitted_node_type != stored_node_type:
        raise HTTPException(
            status_code=409,
            detail={
                "message": "node_type does not match the sensor profile",
                "submitted": submitted_node_type,
                "current": stored_node_type,
            },
        )

    # ---------------------------------------------------------
    # 8. Verify firmware version syntax
    # ---------------------------------------------------------

    firmware_version = str(
        device.firmware_version or ""
    ).strip()

    if firmware_version_tuple(firmware_version) is None:
        raise HTTPException(
            status_code=400,
            detail=(
                "firmware_version is required and must use a numeric "
                "version such as 1.0.0"
            ),
        )

    # ---------------------------------------------------------
    # 9. Check all enabled firmware compatibility requirements
    # ---------------------------------------------------------

    compatibility_rows = conn.execute(
        """
        SELECT
            compatibility.min_firmware_version,
            compatibility.max_firmware_version,
            module.module_key,
            module.display_name
        FROM profile_firmware_compatibility compatibility
        INNER JOIN firmware_modules module
            ON module.id = compatibility.firmware_module_id
        WHERE compatibility.profile_id = ?
          AND compatibility.enabled = 1
          AND module.enabled = 1
        ORDER BY module.module_key
        """,
        (profile["id"],),
    ).fetchall()

    incompatibilities = []

    for row in compatibility_rows:
        if not firmware_version_is_compatible(
            firmware_version,
            row["min_firmware_version"],
            row["max_firmware_version"],
        ):
            incompatibilities.append(
                {
                    "module_key": row["module_key"],
                    "module_name": row["display_name"],
                    "minimum": row["min_firmware_version"],
                    "maximum": row["max_firmware_version"],
                    "current": firmware_version,
                }
            )

    if incompatibilities:
        raise HTTPException(
            status_code=409,
            detail={
                "message": (
                    "Firmware is not compatible with the selected profile"
                ),
                "incompatibilities": incompatibilities,
            },
        )

    # ---------------------------------------------------------
    # 10. Return canonical backend-controlled values
    # ---------------------------------------------------------

    capabilities = profile_json_load(
        profile.get("capabilities_json"),
        [],
    )

    return {
        "profile_id": int(profile["id"]),
        "profile_code": stored_profile_code,
        "profile_name": profile.get("profile_name"),
        "profile_version": stored_profile_version,
        "node_type": stored_node_type,
        "capabilities": capabilities,
        "payload_version": stored_payload_version,
        "payload_encoder_key": stored_encoder_key,
        "f_port": int(profile.get("f_port") or 1),
        "uplink_interval_seconds": stored_interval,
        "firmware_version": firmware_version,
        "configuration_status": "validated",
        "configuration_checksum": profile.get("schema_checksum"),
        "icon_type": profile.get("icon_type") or infer_icon_type(
            stored_node_type
        ),
        "tb_device_profile_name": profile.get(
            "tb_device_profile_name"
        ),
        "ttn_formatter_type": profile.get("ttn_formatter_type"),
        "ttn_formatter_code": profile.get("ttn_formatter_code"),
    }


def validate_sensor_profile_definition(
    conn: sqlite3.Connection,
    data: dict,
    exclude_profile_id: int | None = None,
):
    """
    Validate and normalize a complete sensor-profile definition.

    Returns:
        {
            "valid": bool,
            "errors": list[str],
            "normalized": dict | None,
            "schema_checksum": str | None
        }
    """

    errors = []

    if not isinstance(data, dict):
        return {
            "valid": False,
            "errors": [
                "Profile definition must be a JSON object"
            ],
            "normalized": None,
            "schema_checksum": None,
        }

    # ---------------------------------------------------------
    # Basic profile information
    # ---------------------------------------------------------

    profile_code = str(
        data.get("profile_code") or ""
    ).strip().upper()

    profile_name = str(
        data.get("profile_name") or ""
    ).strip()

    node_type = str(
        data.get("node_type") or ""
    ).strip().lower()

    description = str(
        data.get("description") or ""
    ).strip()

    if not PROFILE_CODE_PATTERN.fullmatch(profile_code):
        errors.append(
            "profile_code must start with an uppercase letter "
            "and contain only A-Z, 0-9 and underscores"
        )

    if not profile_name:
        errors.append("profile_name is required")

    if len(profile_name) > 120:
        errors.append(
            "profile_name must not exceed 120 characters"
        )

    if not PROFILE_KEY_PATTERN.fullmatch(node_type):
        errors.append(
            "node_type must start with a lowercase letter "
            "and contain only lowercase letters, numbers "
            "and underscores"
        )

    existing_profile = None

    if profile_code:
        if exclude_profile_id is None:
            existing_profile = conn.execute(
                """
                SELECT id
                FROM sensor_profiles
                WHERE UPPER(profile_code) = UPPER(?)
                LIMIT 1
                """,
                (profile_code,),
            ).fetchone()
        else:
            existing_profile = conn.execute(
                """
                SELECT id
                FROM sensor_profiles
                WHERE UPPER(profile_code) = UPPER(?)
                  AND id != ?
                LIMIT 1
                """,
                (
                    profile_code,
                    exclude_profile_id,
                ),
            ).fetchone()

    if existing_profile:
        errors.append(
            f"profile_code already exists: {profile_code}"
        )

    # ---------------------------------------------------------
    # Capabilities and configuration schema
    # ---------------------------------------------------------

    capabilities = profile_unique_string_list(
        data.get("capabilities", [])
    )

    if not capabilities:
        errors.append(
            "At least one capability is required"
        )

    for capability in capabilities:
        if not PROFILE_KEY_PATTERN.fullmatch(capability):
            errors.append(
                f"Invalid capability key: {capability}"
            )

    configuration_schema = data.get(
        "configuration_schema",
        {},
    )

    if configuration_schema is None:
        configuration_schema = {}

    if not isinstance(configuration_schema, dict):
        errors.append(
            "configuration_schema must be a JSON object"
        )
        configuration_schema = {}

    # ---------------------------------------------------------
    # Payload and platform configuration
    # ---------------------------------------------------------

    payload_encoder_key = str(
        data.get("payload_encoder_key") or ""
    ).strip().lower()

    if not PROFILE_KEY_PATTERN.fullmatch(
        payload_encoder_key
    ):
        errors.append(
            "payload_encoder_key must contain only lowercase "
            "letters, numbers and underscores"
        )

    profile_version = profile_optional_integer(
        data.get("profile_version", 1),
        "profile_version",
        errors,
        minimum=1,
        maximum=9999,
    )

    payload_version = profile_optional_integer(
        data.get("payload_version", 1),
        "payload_version",
        errors,
        minimum=1,
        maximum=9999,
    )

    f_port = profile_optional_integer(
        data.get("f_port", 1),
        "f_port",
        errors,
        minimum=1,
        maximum=223,
    )

    uplink_interval_seconds = profile_optional_integer(
        data.get("uplink_interval_seconds", 60),
        "uplink_interval_seconds",
        errors,
        minimum=5,
        maximum=86400,
    )

    ttn_formatter_type = str(
        data.get("ttn_formatter_type")
        or "javascript"
    ).strip().lower()

    ttn_formatter_code = str(
        data.get("ttn_formatter_code") or ""
    ).strip()

    if ttn_formatter_type != "javascript":
        errors.append(
            "Only JavaScript TTN formatters are currently supported"
        )

    if not ttn_formatter_code:
        errors.append(
            "ttn_formatter_code is required"
        )

    elif "decodeUplink" not in ttn_formatter_code:
        errors.append(
            "TTN formatter must contain a decodeUplink function"
        )

    tb_device_profile_name = str(
        data.get("tb_device_profile_name") or ""
    ).strip()

    icon_type = str(
        data.get("icon_type") or "default"
    ).strip().lower()

    icon_color = str(
        data.get("icon_color") or ""
    ).strip()

    status = str(
        data.get("status") or "draft"
    ).strip().lower()

    if status not in PROFILE_ALLOWED_STATUSES:
        errors.append(
            "status must be one of: "
            + ", ".join(
                sorted(PROFILE_ALLOWED_STATUSES)
            )
        )

    enabled = profile_value_to_boolean(
        data.get("enabled", True),
        default=True,
    )

    # ---------------------------------------------------------
    # Telemetry fields
    # ---------------------------------------------------------

    raw_fields = data.get("fields", [])

    if not isinstance(raw_fields, list):
        errors.append("fields must be a list")
        raw_fields = []

    if not raw_fields:
        errors.append(
            "At least one telemetry field is required"
        )

    normalized_fields = []
    field_keys = set()

    for index, raw_field in enumerate(raw_fields):
        field_prefix = f"fields[{index}]"

        if not isinstance(raw_field, dict):
            errors.append(
                f"{field_prefix} must be an object"
            )
            continue

        field_key = str(
            raw_field.get("field_key") or ""
        ).strip().lower()

        label = str(
            raw_field.get("label") or ""
        ).strip()

        unit = raw_field.get("unit")

        if unit is not None:
            unit = str(unit).strip() or None

        data_type = str(
            raw_field.get("data_type") or "number"
        ).strip().lower()

        if not PROFILE_KEY_PATTERN.fullmatch(field_key):
            errors.append(
                f"{field_prefix}.field_key is invalid"
            )

        if field_key in field_keys:
            errors.append(
                f"Duplicate field_key: {field_key}"
            )

        field_keys.add(field_key)

        if not label:
            errors.append(
                f"{field_prefix}.label is required"
            )

        if data_type not in PROFILE_ALLOWED_DATA_TYPES:
            errors.append(
                f"{field_prefix}.data_type must be one of: "
                + ", ".join(
                    sorted(PROFILE_ALLOWED_DATA_TYPES)
                )
            )

        payload_order = profile_optional_integer(
            raw_field.get(
                "payload_order",
                index + 1,
            ),
            f"{field_prefix}.payload_order",
            errors,
            minimum=1,
        )

        byte_offset = profile_optional_integer(
            raw_field.get("byte_offset"),
            f"{field_prefix}.byte_offset",
            errors,
            minimum=0,
        )

        byte_length = profile_optional_integer(
            raw_field.get("byte_length"),
            f"{field_prefix}.byte_length",
            errors,
            minimum=1,
        )

        scale = profile_optional_float(
            raw_field.get("scale", 1),
            f"{field_prefix}.scale",
            errors,
        )

        if scale is None:
            scale = 1.0

        display_order = profile_optional_integer(
            raw_field.get(
                "display_order",
                index + 1,
            ),
            f"{field_prefix}.display_order",
            errors,
            minimum=0,
        )

        precision_digits = profile_optional_integer(
            raw_field.get("precision_digits"),
            f"{field_prefix}.precision_digits",
            errors,
            minimum=0,
            maximum=8,
        )

        min_value = profile_optional_float(
            raw_field.get("min_value"),
            f"{field_prefix}.min_value",
            errors,
        )

        max_value = profile_optional_float(
            raw_field.get("max_value"),
            f"{field_prefix}.max_value",
            errors,
        )

        if (
            min_value is not None
            and max_value is not None
            and min_value > max_value
        ):
            errors.append(
                f"{field_prefix}.min_value cannot exceed max_value"
            )

        endianness = str(
            raw_field.get("endianness") or "big"
        ).strip().lower()

        if endianness not in {"big", "little"}:
            errors.append(
                f"{field_prefix}.endianness must be big or little"
            )

        normalized_fields.append(
            {
                "field_key": field_key,
                "label": label,
                "unit": unit,
                "data_type": data_type,
                "payload_order": payload_order,
                "byte_offset": byte_offset,
                "byte_length": byte_length,
                "scale": scale,
                "signed": profile_value_to_boolean(
                    raw_field.get("signed", False)
                ),
                "endianness": endianness,
                "required": profile_value_to_boolean(
                    raw_field.get("required", True)
                ),
                "nullable": profile_value_to_boolean(
                    raw_field.get("nullable", False)
                ),
                "display_order": display_order,
                "precision_digits": precision_digits,
                "visible_floor": profile_value_to_boolean(
                    raw_field.get("visible_floor", True)
                ),
                "visible_dashboard": profile_value_to_boolean(
                    raw_field.get(
                        "visible_dashboard",
                        True,
                    )
                ),
                "min_value": min_value,
                "max_value": max_value,
                "default_value": raw_field.get(
                    "default_value"
                ),
            }
        )

    # ---------------------------------------------------------
    # Sensor components
    # ---------------------------------------------------------

    raw_sensors = data.get("sensors", [])

    if not isinstance(raw_sensors, list):
        errors.append("sensors must be a list")
        raw_sensors = []

    if not raw_sensors:
        errors.append(
            "At least one physical or compatibility sensor "
            "component is required"
        )

    normalized_sensors = []
    sensor_relationship_keys = set()

    for index, raw_sensor in enumerate(raw_sensors):
        sensor_prefix = f"sensors[{index}]"

        if not isinstance(raw_sensor, dict):
            errors.append(
                f"{sensor_prefix} must be an object"
            )
            continue

        sensor_code = str(
            raw_sensor.get("sensor_code") or ""
        ).strip().upper()

        module_key = str(
            raw_sensor.get("module_key") or ""
        ).strip().lower()

        role = str(
            raw_sensor.get("role") or "primary"
        ).strip().lower()

        if not sensor_code:
            errors.append(
                f"{sensor_prefix}.sensor_code is required"
            )

        if not PROFILE_KEY_PATTERN.fullmatch(module_key):
            errors.append(
                f"{sensor_prefix}.module_key is invalid"
            )

        if not PROFILE_KEY_PATTERN.fullmatch(role):
            errors.append(
                f"{sensor_prefix}.role is invalid"
            )

        relationship_key = (
            sensor_code,
            role,
        )

        if relationship_key in sensor_relationship_keys:
            errors.append(
                "Duplicate sensor and role combination: "
                f"{sensor_code}/{role}"
            )

        sensor_relationship_keys.add(
            relationship_key
        )

        sensor_row = conn.execute(
            """
            SELECT id
            FROM sensor_catalog
            WHERE sensor_code = ?
            LIMIT 1
            """,
            (sensor_code,),
        ).fetchone()

        if not sensor_row:
            errors.append(
                f"Unknown sensor_code: {sensor_code}"
            )

        module_row = conn.execute(
            """
            SELECT id
            FROM firmware_modules
            WHERE module_key = ?
            LIMIT 1
            """,
            (module_key,),
        ).fetchone()

        if not module_row:
            errors.append(
                f"Unknown firmware module: {module_key}"
            )

        configuration = raw_sensor.get(
            "configuration",
            {},
        )

        if configuration is None:
            configuration = {}

        if not isinstance(configuration, dict):
            errors.append(
                f"{sensor_prefix}.configuration must be an object"
            )
            configuration = {}

        normalized_sensors.append(
            {
                "sensor_code": sensor_code,
                "module_key": module_key,
                "role": role,
                "required": profile_value_to_boolean(
                    raw_sensor.get("required", True)
                ),
                "configuration": configuration,
                "display_order": profile_optional_integer(
                    raw_sensor.get(
                        "display_order",
                        index + 1,
                    ),
                    f"{sensor_prefix}.display_order",
                    errors,
                    minimum=0,
                ),
            }
        )

    # ---------------------------------------------------------
    # Alarm rules
    # ---------------------------------------------------------

    raw_rules = data.get("rules", [])

    if not isinstance(raw_rules, list):
        errors.append("rules must be a list")
        raw_rules = []

    normalized_rules = []
    rule_codes = set()

    for index, raw_rule in enumerate(raw_rules):
        rule_prefix = f"rules[{index}]"

        if not isinstance(raw_rule, dict):
            errors.append(
                f"{rule_prefix} must be an object"
            )
            continue

        rule_code = str(
            raw_rule.get("rule_code") or ""
        ).strip().upper()

        field_key = str(
            raw_rule.get("field_key") or ""
        ).strip().lower()

        operator = str(
            raw_rule.get("operator") or ""
        ).strip().lower()

        severity = str(
            raw_rule.get("severity") or "warning"
        ).strip().lower()

        alarm_type = str(
            raw_rule.get("alarm_type") or node_type
        ).strip().lower()

        message_template = str(
            raw_rule.get("message_template") or ""
        ).strip()

        if not PROFILE_CODE_PATTERN.fullmatch(rule_code):
            errors.append(
                f"{rule_prefix}.rule_code is invalid"
            )

        if rule_code in rule_codes:
            errors.append(
                f"Duplicate rule_code: {rule_code}"
            )

        rule_codes.add(rule_code)

        if field_key not in field_keys:
            errors.append(
                f"{rule_prefix}.field_key does not exist "
                f"in telemetry fields: {field_key}"
            )

        if operator not in PROFILE_ALLOWED_OPERATORS:
            errors.append(
                f"{rule_prefix}.operator must be one of: "
                + ", ".join(
                    sorted(PROFILE_ALLOWED_OPERATORS)
                )
            )

        if severity not in PROFILE_ALLOWED_SEVERITIES:
            errors.append(
                f"{rule_prefix}.severity must be one of: "
                + ", ".join(
                    sorted(PROFILE_ALLOWED_SEVERITIES)
                )
            )

        if not PROFILE_KEY_PATTERN.fullmatch(alarm_type):
            errors.append(
                f"{rule_prefix}.alarm_type is invalid"
            )

        if not message_template:
            errors.append(
                f"{rule_prefix}.message_template is required"
            )

        threshold_value = profile_optional_float(
            raw_rule.get("threshold_value"),
            f"{rule_prefix}.threshold_value",
            errors,
        )

        threshold_value_2 = profile_optional_float(
            raw_rule.get("threshold_value_2"),
            f"{rule_prefix}.threshold_value_2",
            errors,
        )

        expected_boolean = raw_rule.get(
            "expected_boolean"
        )

        if expected_boolean is not None:
            expected_boolean = profile_value_to_boolean(
                expected_boolean
            )

        expected_text = raw_rule.get(
            "expected_text"
        )

        if expected_text is not None:
            expected_text = str(expected_text)

        if operator in {
            ">",
            ">=",
            "<",
            "<=",
        }:
            if threshold_value is None:
                errors.append(
                    f"{rule_prefix}.threshold_value is required "
                    f"for operator {operator}"
                )

        if operator in {
            "between",
            "outside",
        }:
            if (
                threshold_value is None
                or threshold_value_2 is None
            ):
                errors.append(
                    f"{rule_prefix} requires two threshold values"
                )

            elif threshold_value > threshold_value_2:
                errors.append(
                    f"{rule_prefix}.threshold_value cannot "
                    "exceed threshold_value_2"
                )

        if operator in {"==", "!="}:
            if (
                threshold_value is None
                and expected_boolean is None
                and expected_text is None
            ):
                errors.append(
                    f"{rule_prefix} requires a threshold, "
                    "Boolean or text comparison value"
                )

        if operator == "contains" and expected_text is None:
            errors.append(
                f"{rule_prefix}.expected_text is required "
                "for contains"
            )

        normalized_rules.append(
            {
                "rule_code": rule_code,
                "field_key": field_key,
                "operator": operator,
                "threshold_value": threshold_value,
                "threshold_value_2": threshold_value_2,
                "expected_boolean": expected_boolean,
                "expected_text": expected_text,
                "severity": severity,
                "alarm_type": alarm_type,
                "message_template": message_template,
                "debounce_seconds": profile_optional_integer(
                    raw_rule.get(
                        "debounce_seconds",
                        0,
                    ),
                    f"{rule_prefix}.debounce_seconds",
                    errors,
                    minimum=0,
                    maximum=86400,
                ),
                "cooldown_seconds": profile_optional_integer(
                    raw_rule.get(
                        "cooldown_seconds",
                        300,
                    ),
                    f"{rule_prefix}.cooldown_seconds",
                    errors,
                    minimum=0,
                    maximum=604800,
                ),
                "auto_resolve": profile_value_to_boolean(
                    raw_rule.get("auto_resolve", True)
                ),
                "enabled": profile_value_to_boolean(
                    raw_rule.get("enabled", True)
                ),
            }
        )

    normalized = {
        "profile_code": profile_code,
        "profile_name": profile_name,
        "profile_version": profile_version,
        "node_type": node_type,
        "description": description,
        "capabilities": capabilities,
        "configuration_schema": configuration_schema,
        "payload_encoder_key": payload_encoder_key,
        "payload_version": payload_version,
        "f_port": f_port,
        "uplink_interval_seconds": (
            uplink_interval_seconds
        ),
        "ttn_formatter_code": ttn_formatter_code,
        "ttn_formatter_type": ttn_formatter_type,
        "tb_device_profile_name": (
            tb_device_profile_name or None
        ),
        "icon_type": icon_type,
        "icon_color": icon_color or None,
        "status": status,
        "enabled": enabled,
        "fields": normalized_fields,
        "rules": normalized_rules,
        "sensors": normalized_sensors,
    }

    schema_checksum = None

    if not errors:
        schema_checksum = (
            calculate_sensor_profile_checksum(
                normalized
            )
        )

    return {
        "valid": len(errors) == 0,
        "errors": errors,
        "normalized": normalized,
        "schema_checksum": schema_checksum,
    }

# =============================================================
# SENSOR PROFILE WRITE SERVICE
# =============================================================

def profile_utc_now_iso():
    """
    Return the current UTC time in ISO 8601 format.
    """

    return datetime.now(timezone.utc).isoformat()


def insert_sensor_profile_version_snapshot(
    conn: sqlite3.Connection,
    profile_id: int,
    version: int,
    normalized_definition: dict,
    schema_checksum: str,
    change_note: str,
    actor: str,
):
    """
    Store one immutable profile-version snapshot.
    """

    snapshot = {
        "profile_id": profile_id,
        "version": version,
        "schema_checksum": schema_checksum,
        "definition": normalized_definition,
    }

    conn.execute(
        """
        INSERT INTO sensor_profile_versions(
            profile_id,
            version,
            snapshot_json,
            change_note,
            created_by,
            created_at
        )
        VALUES (?, ?, ?, ?, ?, ?)
        """,
        (
            profile_id,
            version,
            json.dumps(
                snapshot,
                ensure_ascii=False,
                sort_keys=True,
            ),
            change_note,
            actor,
            profile_utc_now_iso(),
        ),
    )


def replace_sensor_profile_children(
    conn: sqlite3.Connection,
    profile_id: int,
    normalized_definition: dict,
):
    """
    Replace the profile's telemetry fields, alarm rules,
    sensor relationships and firmware compatibility records.

    This function does not commit the transaction.
    """

    conn.execute(
        """
        DELETE FROM profile_firmware_compatibility
        WHERE profile_id = ?
        """,
        (profile_id,),
    )

    conn.execute(
        """
        DELETE FROM sensor_profile_sensors
        WHERE profile_id = ?
        """,
        (profile_id,),
    )

    conn.execute(
        """
        DELETE FROM sensor_profile_fields
        WHERE profile_id = ?
        """,
        (profile_id,),
    )

    conn.execute(
        """
        DELETE FROM sensor_profile_rules
        WHERE profile_id = ?
        """,
        (profile_id,),
    )

    # ---------------------------------------------------------
    # Physical sensors and firmware modules
    # ---------------------------------------------------------

    compatibility_modules = set()

    for component in normalized_definition["sensors"]:
        sensor_row = conn.execute(
            """
            SELECT id
            FROM sensor_catalog
            WHERE sensor_code = ?
              AND enabled = 1
            LIMIT 1
            """,
            (component["sensor_code"],),
        ).fetchone()

        if not sensor_row:
            raise ValueError(
                "Sensor is missing or disabled: "
                + component["sensor_code"]
            )

        module_row = conn.execute(
            """
            SELECT
                id,
                min_firmware_version
            FROM firmware_modules
            WHERE module_key = ?
              AND enabled = 1
            LIMIT 1
            """,
            (component["module_key"],),
        ).fetchone()

        if not module_row:
            raise ValueError(
                "Firmware module is missing or disabled: "
                + component["module_key"]
            )

        conn.execute(
            """
            INSERT INTO sensor_profile_sensors(
                profile_id,
                sensor_id,
                firmware_module_id,
                role,
                required,
                configuration_json,
                display_order
            )
            VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                profile_id,
                sensor_row["id"],
                module_row["id"],
                component["role"],
                int(component["required"]),
                json.dumps(
                    component["configuration"],
                    ensure_ascii=False,
                    sort_keys=True,
                ),
                component["display_order"],
            ),
        )

        firmware_module_id = module_row["id"]

        if firmware_module_id in compatibility_modules:
            continue

        compatibility_modules.add(firmware_module_id)

        required_features = [
            normalized_definition["payload_encoder_key"],
            (
                "payload_v"
                + str(
                    normalized_definition[
                        "payload_version"
                    ]
                )
            ),
        ]

        conn.execute(
            """
            INSERT INTO profile_firmware_compatibility(
                profile_id,
                firmware_module_id,
                min_firmware_version,
                max_firmware_version,
                hardware_revision,
                required_features_json,
                enabled
            )
            VALUES (?, ?, ?, ?, ?, ?, 1)
            """,
            (
                profile_id,
                firmware_module_id,
                module_row["min_firmware_version"],
                None,
                None,
                json.dumps(required_features),
            ),
        )

    # ---------------------------------------------------------
    # Telemetry fields
    # ---------------------------------------------------------

    for field in normalized_definition["fields"]:
        conn.execute(
            """
            INSERT INTO sensor_profile_fields(
                profile_id,
                field_key,
                label,
                unit,
                data_type,

                payload_order,
                byte_offset,
                byte_length,
                scale,
                signed,
                endianness,

                required,
                nullable,

                display_order,
                precision_digits,

                visible_floor,
                visible_dashboard,

                min_value,
                max_value,
                default_value_json,

                created_at,
                updated_at
            )
            VALUES (
                ?, ?, ?, ?, ?,
                ?, ?, ?, ?, ?, ?,
                ?, ?,
                ?, ?,
                ?, ?,
                ?, ?, ?,
                ?, ?
            )
            """,
            (
                profile_id,
                field["field_key"],
                field["label"],
                field["unit"],
                field["data_type"],

                field["payload_order"],
                field["byte_offset"],
                field["byte_length"],
                field["scale"],
                int(field["signed"]),
                field["endianness"],

                int(field["required"]),
                int(field["nullable"]),

                field["display_order"],
                field["precision_digits"],

                int(field["visible_floor"]),
                int(field["visible_dashboard"]),

                field["min_value"],
                field["max_value"],
                json.dumps(
                    field["default_value"],
                    ensure_ascii=False,
                ),

                profile_utc_now_iso(),
                profile_utc_now_iso(),
            ),
        )

    # ---------------------------------------------------------
    # Dynamic alarm rules
    # ---------------------------------------------------------

    for rule in normalized_definition["rules"]:
        expected_boolean = rule["expected_boolean"]

        if expected_boolean is not None:
            expected_boolean = int(expected_boolean)

        conn.execute(
            """
            INSERT INTO sensor_profile_rules(
                profile_id,
                rule_code,
                field_key,
                operator,

                threshold_value,
                threshold_value_2,
                expected_boolean,
                expected_text,

                severity,
                alarm_type,
                message_template,

                debounce_seconds,
                cooldown_seconds,
                auto_resolve,
                enabled,

                created_at,
                updated_at
            )
            VALUES (
                ?, ?, ?, ?,
                ?, ?, ?, ?,
                ?, ?, ?,
                ?, ?, ?, ?,
                ?, ?
            )
            """,
            (
                profile_id,
                rule["rule_code"],
                rule["field_key"],
                rule["operator"],

                rule["threshold_value"],
                rule["threshold_value_2"],
                expected_boolean,
                rule["expected_text"],

                rule["severity"],
                rule["alarm_type"],
                rule["message_template"],

                rule["debounce_seconds"],
                rule["cooldown_seconds"],
                int(rule["auto_resolve"]),
                int(rule["enabled"]),

                profile_utc_now_iso(),
                profile_utc_now_iso(),
            ),
        )


def create_sensor_profile_record(
    conn: sqlite3.Connection,
    profile_definition: dict,
    actor: str = "admin",
    change_note: str = "Profile created",
):
    """
    Validate and create a new non-system sensor profile.

    This function does not commit the transaction.
    """

    definition = dict(profile_definition or {})

    definition["profile_version"] = 1
    definition.setdefault("payload_version", 1)
    definition.setdefault("status", "draft")
    definition.setdefault("enabled", True)

    validation = validate_sensor_profile_definition(
        conn,
        definition,
    )

    if not validation["valid"]:
        raise ValueError(
            "Profile validation failed: "
            + "; ".join(validation["errors"])
        )

    normalized = validation["normalized"]
    schema_checksum = validation["schema_checksum"]
    now = profile_utc_now_iso()

    cursor = conn.execute(
        """
        INSERT INTO sensor_profiles(
            profile_code,
            profile_name,
            profile_version,
            node_type,
            description,

            capabilities_json,
            configuration_schema_json,

            payload_encoder_key,
            payload_version,
            f_port,
            uplink_interval_seconds,

            ttn_formatter_code,
            ttn_formatter_type,

            tb_device_profile_name,

            icon_type,
            icon_color,

            status,
            enabled,
            is_system,

            schema_checksum,
            created_by,
            updated_by,
            created_at,
            updated_at
        )
        VALUES (
            ?, ?, ?, ?, ?,
            ?, ?,
            ?, ?, ?, ?,
            ?, ?,
            ?,
            ?, ?,
            ?, ?, 0,
            ?, ?, ?, ?, ?
        )
        """,
        (
            normalized["profile_code"],
            normalized["profile_name"],
            normalized["profile_version"],
            normalized["node_type"],
            normalized["description"],

            json.dumps(
                normalized["capabilities"],
                ensure_ascii=False,
            ),
            json.dumps(
                normalized["configuration_schema"],
                ensure_ascii=False,
                sort_keys=True,
            ),

            normalized["payload_encoder_key"],
            normalized["payload_version"],
            normalized["f_port"],
            normalized["uplink_interval_seconds"],

            normalized["ttn_formatter_code"],
            normalized["ttn_formatter_type"],

            normalized["tb_device_profile_name"],

            normalized["icon_type"],
            normalized["icon_color"],

            normalized["status"],
            int(normalized["enabled"]),

            schema_checksum,
            actor,
            actor,
            now,
            now,
        ),
    )

    profile_id = cursor.lastrowid

    replace_sensor_profile_children(
        conn,
        profile_id,
        normalized,
    )

    insert_sensor_profile_version_snapshot(
        conn,
        profile_id,
        normalized["profile_version"],
        normalized,
        schema_checksum,
        change_note,
        actor,
    )

    return get_sensor_profile_detail(
        conn,
        profile_id,
        include_formatter=True,
    )


def update_sensor_profile_record(
    conn: sqlite3.Connection,
    profile_id: int,
    profile_definition: dict,
    actor: str = "admin",
    change_note: str = "Profile updated",
):
    """
    Update a custom profile and create a new profile version.

    Seeded system profiles are immutable and must be cloned first.
    This function does not commit the transaction.
    """

    existing = get_sensor_profile_detail(
        conn,
        profile_id,
        include_formatter=True,
    )

    if not existing:
        raise ValueError(
            "Sensor profile not found: "
            + str(profile_id)
        )

    if existing["is_system"]:
        raise ValueError(
            "System profiles cannot be edited directly. "
            "Clone the profile and edit the clone."
        )

    supplied_code = profile_definition.get(
        "profile_code"
    )

    if (
        supplied_code is not None
        and str(supplied_code).strip().upper()
        != existing["profile_code"]
    ):
        raise ValueError(
            "profile_code cannot be changed after creation"
        )

    merged_definition = {
        "profile_code": existing["profile_code"],
        "profile_name": existing["profile_name"],
        "profile_version": existing["profile_version"],
        "node_type": existing["node_type"],
        "description": existing["description"],
        "capabilities": existing["capabilities"],
        "configuration_schema": existing[
            "configuration_schema"
        ],
        "payload_encoder_key": existing[
            "payload_encoder_key"
        ],
        "payload_version": existing["payload_version"],
        "f_port": existing["f_port"],
        "uplink_interval_seconds": existing[
            "uplink_interval_seconds"
        ],
        "ttn_formatter_code": existing[
            "ttn_formatter_code"
        ],
        "ttn_formatter_type": existing[
            "ttn_formatter_type"
        ],
        "tb_device_profile_name": existing[
            "tb_device_profile_name"
        ],
        "icon_type": existing["icon_type"],
        "icon_color": existing["icon_color"],
        "status": existing["status"],
        "enabled": existing["enabled"],
        "fields": existing["fields"],
        "rules": existing["rules"],
        "sensors": existing["sensors"],
    }

    merged_definition.update(
        dict(profile_definition or {})
    )

    next_version = int(
        existing["profile_version"]
    ) + 1

    merged_definition["profile_code"] = existing[
        "profile_code"
    ]

    merged_definition["profile_version"] = (
        next_version
    )

    validation = validate_sensor_profile_definition(
        conn,
        merged_definition,
        exclude_profile_id=profile_id,
    )

    if not validation["valid"]:
        raise ValueError(
            "Profile validation failed: "
            + "; ".join(validation["errors"])
        )

    normalized = validation["normalized"]
    schema_checksum = validation["schema_checksum"]
    now = profile_utc_now_iso()

    conn.execute(
        """
        UPDATE sensor_profiles
        SET
            profile_name = ?,
            profile_version = ?,
            node_type = ?,
            description = ?,

            capabilities_json = ?,
            configuration_schema_json = ?,

            payload_encoder_key = ?,
            payload_version = ?,
            f_port = ?,
            uplink_interval_seconds = ?,

            ttn_formatter_code = ?,
            ttn_formatter_type = ?,

            tb_device_profile_name = ?,

            icon_type = ?,
            icon_color = ?,

            status = ?,
            enabled = ?,

            schema_checksum = ?,
            updated_by = ?,
            updated_at = ?

        WHERE id = ?
        """,
        (
            normalized["profile_name"],
            normalized["profile_version"],
            normalized["node_type"],
            normalized["description"],

            json.dumps(
                normalized["capabilities"],
                ensure_ascii=False,
            ),
            json.dumps(
                normalized["configuration_schema"],
                ensure_ascii=False,
                sort_keys=True,
            ),

            normalized["payload_encoder_key"],
            normalized["payload_version"],
            normalized["f_port"],
            normalized["uplink_interval_seconds"],

            normalized["ttn_formatter_code"],
            normalized["ttn_formatter_type"],

            normalized["tb_device_profile_name"],

            normalized["icon_type"],
            normalized["icon_color"],

            normalized["status"],
            int(normalized["enabled"]),

            schema_checksum,
            actor,
            now,

            profile_id,
        ),
    )

    replace_sensor_profile_children(
        conn,
        profile_id,
        normalized,
    )

    insert_sensor_profile_version_snapshot(
        conn,
        profile_id,
        normalized["profile_version"],
        normalized,
        schema_checksum,
        change_note,
        actor,
    )

    return get_sensor_profile_detail(
        conn,
        profile_id,
        include_formatter=True,
    )


def generate_unique_sensor_profile_code(
    conn: sqlite3.Connection,
    profile_name: str,
):
    """
    Generate an internal profile code without requiring the
    administrator to enter technical identifiers.
    """

    clean_name = re.sub(
        r"[^A-Z0-9]+",
        "_",
        str(profile_name or "").strip().upper(),
    ).strip("_")

    if not clean_name:
        clean_name = "SENSOR_PROFILE"

    if not clean_name[0].isalpha():
        clean_name = "PROFILE_" + clean_name

    clean_name = clean_name[:52].rstrip("_")

    if len(clean_name) < 3:
        clean_name = "SENSOR_PROFILE"

    base_code = (
        clean_name + "_V1"
    )[:64].rstrip("_")

    candidate = base_code
    suffix_number = 2

    while conn.execute(
        """
        SELECT 1
        FROM sensor_profiles
        WHERE UPPER(profile_code) = UPPER(?)
        LIMIT 1
        """,
        (candidate,),
    ).fetchone():

        suffix = "_" + str(suffix_number)

        candidate = (
            base_code[
                :64 - len(suffix)
            ].rstrip("_")
            + suffix
        )

        suffix_number += 1

    return candidate


def clone_sensor_profile_record(
    conn: sqlite3.Connection,
    source_profile_identifier,
    new_profile_code: str,
    new_profile_name: str,
    actor: str = "admin",
    activate: bool = False,
    uplink_interval_seconds: int | None = None,
    alarm_thresholds: dict | None = None,
):
    """
    Clone an existing sensor profile while preserving its complete
    technical configuration.

    Simple administrator creation can:
    - Generate the profile code automatically.
    - Activate the profile immediately.
    - Override the uplink interval.
    - Override numeric alarm thresholds.

    The existing advanced clone workflow remains compatible.

    This function does not commit the transaction.
    """

    source = get_sensor_profile_detail(
        conn,
        source_profile_identifier,
        include_formatter=True,
    )

    if not source:
        raise ValueError(
            "Source sensor profile was not found"
        )

    clean_profile_name = str(
        new_profile_name or ""
    ).strip()

    clean_profile_code = str(
        new_profile_code or ""
    ).strip().upper()

    if not clean_profile_name:
        raise ValueError(
            "New profile name is required"
        )

    if not clean_profile_code:
        clean_profile_code = (
            generate_unique_sensor_profile_code(
                conn,
                clean_profile_name,
            )
        )

    # =========================================================
    # UPLINK INTERVAL
    # =========================================================

    source_interval = int(
        source.get(
            "uplink_interval_seconds"
        )
        or 60
    )

    if uplink_interval_seconds in (
        None,
        "",
    ):
        selected_interval = source_interval

    else:
        try:
            selected_interval = int(
                uplink_interval_seconds
            )

        except Exception:
            raise ValueError(
                "Uplink interval must be an integer"
            )

        if not (
            5
            <= selected_interval
            <= 86400
        ):
            raise ValueError(
                "Uplink interval must be between "
                "5 and 86400 seconds"
            )

    # =========================================================
    # SIMPLE CREATION VALIDATION
    # =========================================================

    if activate:
        if not bool(
            source.get("enabled")
        ):
            raise ValueError(
                "Disabled templates cannot be used "
                "for simple profile creation"
            )

        source_status = str(
            source.get("status") or ""
        ).strip().lower()

        if source_status != "active":
            raise ValueError(
                "Only active templates can be used "
                "for simple profile creation"
            )

    # =========================================================
    # OPTIONAL ALARM THRESHOLD OVERRIDES
    # =========================================================

    if alarm_thresholds is None:
        alarm_thresholds = {}

    if not isinstance(
        alarm_thresholds,
        dict,
    ):
        raise ValueError(
            "alarm_thresholds must be an object"
        )

    copied_rules = []

    for source_rule in source.get(
        "rules",
        [],
    ):
        rule = dict(source_rule)

        rule_code = str(
            rule.get("rule_code") or ""
        ).strip().upper()

        field_key = str(
            rule.get("field_key") or ""
        ).strip().lower()

        override = None

        if rule_code in alarm_thresholds:
            override = alarm_thresholds[
                rule_code
            ]

        elif field_key in alarm_thresholds:
            override = alarm_thresholds[
                field_key
            ]

        if override is not None:
            if not isinstance(
                override,
                dict,
            ):
                override = {
                    "threshold_value": override
                }

            for threshold_key in (
                "threshold_value",
                "threshold_value_2",
            ):
                if threshold_key not in override:
                    continue

                raw_value = override.get(
                    threshold_key
                )

                if raw_value in (
                    None,
                    "",
                ):
                    continue

                try:
                    rule[threshold_key] = float(
                        raw_value
                    )

                except Exception:
                    raise ValueError(
                        f"{rule_code} "
                        f"{threshold_key} "
                        "must be numeric"
                    )

        copied_rules.append(rule)

    # =========================================================
    # COMPLETE PROFILE DEFINITION
    # =========================================================

    clone_definition = {
        "profile_code": clean_profile_code,

        "profile_name": clean_profile_name,

        "profile_version": 1,

        "node_type": source["node_type"],

        "description": (
            "Created from the supported template "
            + source["profile_name"]
            + ". "
            + str(
                source.get("description")
                or ""
            )
        ).strip(),

        "capabilities": source[
            "capabilities"
        ],

        "configuration_schema": source[
            "configuration_schema"
        ],

        "payload_encoder_key": source[
            "payload_encoder_key"
        ],

        "payload_version": source[
            "payload_version"
        ],

        "f_port": source["f_port"],

        "uplink_interval_seconds": (
            selected_interval
        ),

        "ttn_formatter_code": source[
            "ttn_formatter_code"
        ],

        "ttn_formatter_type": source[
            "ttn_formatter_type"
        ],

        "tb_device_profile_name": source[
            "tb_device_profile_name"
        ],

        "icon_type": source[
            "icon_type"
        ],

        "icon_color": source[
            "icon_color"
        ],

        "status": (
            "active"
            if activate
            else "draft"
        ),

        "enabled": True,

        "fields": source[
            "fields"
        ],

        "rules": copied_rules,

        "sensors": source[
            "sensors"
        ],
    }

    change_note = (
        "Created from supported template "
        + source["profile_code"]
        if activate
        else
        "Cloned from profile "
        + source["profile_code"]
    )

    return create_sensor_profile_record(
        conn,
        clone_definition,
        actor=actor,
        change_note=change_note,
    )


def set_sensor_profile_enabled(
    conn: sqlite3.Connection,
    profile_identifier,
    enabled: bool,
    actor: str = "admin",
):
    """
    Enable or disable a sensor profile.

    This function does not create a new schema version because
    the profile structure is not being changed.
    """

    profile = get_sensor_profile_detail(
        conn,
        profile_identifier,
        include_formatter=True,
    )

    if not profile:
        raise ValueError(
            "Sensor profile was not found"
        )

    conn.execute(
        """
        UPDATE sensor_profiles
        SET
            enabled = ?,
            updated_by = ?,
            updated_at = ?
        WHERE id = ?
        """,
        (
            int(bool(enabled)),
            actor,
            profile_utc_now_iso(),
            profile["id"],
        ),
    )

    return get_sensor_profile_detail(
        conn,
        profile["id"],
        include_formatter=True,
    )


def delete_sensor_profile_record(
    conn: sqlite3.Connection,
    profile_identifier,
):
    """
    Delete an unused custom profile.

    System profiles, assigned profiles and profiles referenced
    by configuration history cannot be deleted.
    """

    profile = get_sensor_profile_detail(
        conn,
        profile_identifier,
        include_formatter=False,
    )

    if not profile:
        raise ValueError(
            "Sensor profile was not found"
        )

    if profile["is_system"]:
        raise ValueError(
            "System profiles cannot be deleted"
        )

    assigned_device_count = conn.execute(
        """
        SELECT COUNT(*) AS total
        FROM devices
        WHERE profile_id = ?
           OR profile_code = ?
        """,
        (
            profile["id"],
            profile["profile_code"],
        ),
    ).fetchone()["total"]

    if assigned_device_count > 0:
        raise ValueError(
            "Profile cannot be deleted because it is "
            "assigned to one or more devices"
        )

    configuration_history_count = conn.execute(
        """
        SELECT COUNT(*) AS total
        FROM device_configuration_history
        WHERE profile_id = ?
           OR profile_code = ?
        """,
        (
            profile["id"],
            profile["profile_code"],
        ),
    ).fetchone()["total"]

    if configuration_history_count > 0:
        raise ValueError(
            "Profile cannot be deleted because device "
            "configuration history references it. "
            "Disable or archive the profile instead."
        )

    deleted_result = {
        "id": profile["id"],
        "profile_code": profile["profile_code"],
        "profile_name": profile["profile_name"],
    }

    conn.execute(
        """
        DELETE FROM sensor_profiles
        WHERE id = ?
        """,
        (profile["id"],),
    )

    return deleted_result

