@app.middleware("http")
async def auth_middleware(request: Request, call_next):
    path = request.url.path

    public_paths = (
        "/",
        "/login",
        "/admin-login",
        "/client-login",
        "/auth/login",
        "/auth/status",
        "/logout",
        "/me",
        "/docs",
        "/redoc",
        "/openapi.json",
        "/favicon.ico"
    )

    if path in public_paths:
        return await call_next(request)

    public_prefixes = (
        "/uploads",
        "/ttn-webhook",
        "/provision"
    )

    for prefix in public_prefixes:
        if path.startswith(prefix):
            return await call_next(request)

    # CLIENT PORTAL PROTECTION
    if path == "/client-portal" or path.startswith("/client-portal/"):
        current_user = get_current_user_from_request(request)

        if not current_user:
            return login_redirect_for_request(request, "/client-login")

        role = (current_user.get("role") or "").lower()

        if role == "admin":
            return await call_next(request)

        if role != "client":
            return JSONResponse(
                {"detail": "Client role required"},
                status_code=403
            )

        requested_user_id = get_requested_client_user_id(request)

        if requested_user_id is None:
            return RedirectResponse(
                url=f"/client-portal?user_id={current_user['id']}",
                status_code=302
            )

        if requested_user_id != current_user["id"]:
            return JSONResponse(
                {"detail": "You can only access your own client portal"},
                status_code=403
            )

        return await call_next(request)

    # ADMIN PROTECTION
    if is_admin_path(path):
        current_user = get_current_user_from_request(request)

        if not current_user:
            return login_redirect_for_request(request, "/admin-login")

        role = (current_user.get("role") or "").lower()

        if role != "admin":
            return JSONResponse(
                {"detail": "Admin role required"},
                status_code=403
            )

    return await call_next(request)


@app.post("/auth/login")
def auth_login(data: dict, request: Request):
    ensure_default_admin_user()

    email = data.get("email", "").strip().lower()
    password = data.get("password", "")
    next_url = data.get("next", "")
    expected_role = data.get("expected_role", "").strip().lower()

    if not email:
        raise HTTPException(status_code=400, detail="Email is required")

    if not password:
        raise HTTPException(status_code=400, detail="Password is required")

    conn = db()

    cleanup_expired_sessions(conn)

    user_row = conn.execute("""
        SELECT *
        FROM users
        WHERE email = ?
        LIMIT 1
    """, (email,)).fetchone()

    if not user_row:
        conn.close()
        raise HTTPException(status_code=401, detail="Invalid email or password")

    user = dict(user_row)

    if user.get("enabled") != 1:
        conn.close()
        raise HTTPException(status_code=403, detail="User is disabled")

    if not verify_password(password, user_row):
        conn.close()
        raise HTTPException(status_code=401, detail="Invalid email or password")

    actual_role = (user.get("role") or "").lower()

    if expected_role == "admin" and actual_role != "admin":
        conn.close()
        raise HTTPException(
            status_code=403,
            detail="This is not an admin account. Please use the Client Login page."
        )

    if expected_role == "client" and actual_role != "client":
        conn.close()
        raise HTTPException(
            status_code=403,
            detail="This is not a client account. Please use the Admin Login page."
        )

    conn.execute("""
        UPDATE users
        SET last_login_at = CURRENT_TIMESTAMP
        WHERE id = ?
    """, (user["id"],))

    conn.commit()

    updated_user = conn.execute("""
        SELECT *
        FROM users
        WHERE id = ?
        LIMIT 1
    """, (user["id"],)).fetchone()

    safe_user = safe_user_dict(updated_user)

    raw_token = create_login_session(
        conn=conn,
        user_id=safe_user["id"],
        request=request
    )

    conn.close()

    redirect_to = default_redirect_for_user(safe_user)

    if next_url and isinstance(next_url, str) and next_url.startswith("/"):
        clean_next_path = next_url.split("?")[0]

        if actual_role == "admin" and is_admin_path(clean_next_path):
            redirect_to = next_url

        elif actual_role == "client" and next_url.startswith("/client-portal"):
            redirect_to = next_url

    response = JSONResponse({
        "status": "logged_in",
        "user": safe_user,
        "redirect_to": redirect_to
    })

    response.set_cookie(
        key=SESSION_COOKIE_NAME,
        value=raw_token,
        httponly=True,
        samesite="lax",
        max_age=SESSION_TTL_SECONDS
    )

    return response






@app.get("/logout")
def logout(request: Request):
    revoke_current_session(request)

    response = RedirectResponse(url="/login", status_code=302)

    response.delete_cookie(SESSION_COOKIE_NAME)

    return response


