@app.get("/auth/status")
def auth_status():
    ensure_default_admin_user()

    conn = db()

    admin = conn.execute("""
        SELECT id, name, email, role, enabled, last_login_at, created_at
        FROM users
        WHERE email = ?
        LIMIT 1
    """, (ADMIN_EMAIL,)).fetchone()

    session_table = conn.execute("""
        SELECT name
        FROM sqlite_master
        WHERE type = 'table'
          AND name = 'auth_sessions'
    """).fetchone()

    conn.close()

    return {
        "status": "auth_foundation_ready",
        "admin_user": dict(admin) if admin else None,
        "session_table_exists": True if session_table else False,
        "session_cookie_name": SESSION_COOKIE_NAME,
        "session_ttl_seconds": SESSION_TTL_SECONDS,
        "password_hashing": {
            "algorithm": "PBKDF2-HMAC-SHA256",
            "iterations": PASSWORD_PBKDF2_ITERATIONS
        }
    }

def is_admin_path(path: str):
    """
    Return True when a path must be accessible only by an
    authenticated administrator.
    """

    admin_prefixes = (
        "/admin",
        "/audit-log",
        "/alarms",
        "/alarm-settings",
        "/users",
        "/user-access",
        "/client-access-manager",
        "/gateway-monitor",
        "/gateway-placement",
        "/gateway-placement-editor",
        "/floor-editor",
        "/floor-live-view",
        "/building-overview",
        "/device-capabilities-manager",

        # Sensor Profile Manager
        "/sensor-profile-manager",
        "/sensor-profile-editor",
        "/sensor-profiles",
        "/sensor-catalog-manager",
        "/sensor-catalog",
        "/firmware-module-manager",
        "/firmware-modules",
    )

    for prefix in admin_prefixes:
        if path == prefix or path.startswith(prefix + "/"):
            return True

    return False



def login_redirect_for_request(request: Request, login_path: str = "/admin-login"):
    next_path = request.url.path

    if request.url.query:
        next_path += "?" + request.url.query

    return RedirectResponse(
        url=login_path + "?next=" + quote(next_path),
        status_code=302
    )

