def get_requested_client_user_id(request: Request):
    path = request.url.path

    query_user_id = request.query_params.get("user_id")

    if query_user_id:
        try:
            return int(query_user_id)
        except Exception:
            return None

    parts = path.strip("/").split("/")

    if len(parts) >= 2 and parts[0] == "client-portal":
        try:
            return int(parts[1])
        except Exception:
            return None

    return None

@app.put("/users/{user_id}/credentials")
def update_user_credentials(user_id: int, data: dict, request: Request):
    current_user = get_current_user_from_request(request)

    if not current_user:
        raise HTTPException(status_code=401, detail="Not logged in")

    if (current_user.get("role") or "").lower() != "admin":
        raise HTTPException(status_code=403, detail="Admin role required")

    name = data.get("name")
    email = data.get("email")
    password = data.get("password")
    enabled = data.get("enabled")

    conn = db()

    user_row = conn.execute("""
        SELECT *
        FROM users
        WHERE id = ?
        LIMIT 1
    """, (user_id,)).fetchone()

    if not user_row:
        conn.close()
        raise HTTPException(status_code=404, detail="User not found")

    old_user = dict(user_row)

    if (old_user.get("role") or "").lower() != "client":
        conn.close()
        raise HTTPException(
            status_code=400,
            detail="This endpoint is only for client user credentials"
        )

    updates = []
    params = []
    changed_fields = {}

    if name is not None:
        clean_name = str(name).strip()

        if not clean_name:
            conn.close()
            raise HTTPException(status_code=400, detail="Name cannot be empty")

        updates.append("name = ?")
        params.append(clean_name)
        changed_fields["name"] = {
            "old": old_user.get("name"),
            "new": clean_name
        }

    if email is not None:
        clean_email = str(email).strip().lower()

        if not clean_email:
            conn.close()
            raise HTTPException(status_code=400, detail="Email cannot be empty")

        existing_email = conn.execute("""
            SELECT id
            FROM users
            WHERE email = ?
              AND id != ?
            LIMIT 1
        """, (clean_email, user_id)).fetchone()

        if existing_email:
            conn.close()
            raise HTTPException(
                status_code=409,
                detail="Another user already uses this email"
            )

        updates.append("email = ?")
        params.append(clean_email)
        changed_fields["email"] = {
            "old": old_user.get("email"),
            "new": clean_email
        }

    if enabled is not None:
        enabled_value = 1 if enabled in [1, "1", True, "true", "True", "yes", "on"] else 0

        updates.append("enabled = ?")
        params.append(enabled_value)
        changed_fields["enabled"] = {
            "old": old_user.get("enabled"),
            "new": enabled_value
        }

    if password is not None and str(password).strip() != "":
        clean_password = str(password)

        if len(clean_password) < 8:
            conn.close()
            raise HTTPException(
                status_code=400,
                detail="Password must be at least 8 characters"
            )

        password_data = create_password_hash(clean_password)

        updates.append("password_salt = ?")
        params.append(password_data["password_salt"])

        updates.append("password_hash = ?")
        params.append(password_data["password_hash"])

        updates.append("password_iterations = ?")
        params.append(password_data["password_iterations"])

        updates.append("password_updated_at = CURRENT_TIMESTAMP")

        changed_fields["password"] = {
            "old": "***hidden***",
            "new": "***updated***"
        }

    if not updates:
        conn.close()
        raise HTTPException(status_code=400, detail="No credential fields provided")

    params.append(user_id)

    conn.execute(f"""
        UPDATE users
        SET {", ".join(updates)}
        WHERE id = ?
    """, params)

    conn.commit()

    updated_user_row = conn.execute("""
        SELECT *
        FROM users
        WHERE id = ?
        LIMIT 1
    """, (user_id,)).fetchone()

    updated_user = safe_user_dict(updated_user_row)

    log_audit_event(
        conn=conn,
        action="update_client_credentials",
        actor=current_user.get("email", "admin"),
        target_type="user",
        target_id=user_id,
        user_id=user_id,
        details={
            "old": {
                "id": old_user.get("id"),
                "name": old_user.get("name"),
                "email": old_user.get("email"),
                "role": old_user.get("role"),
                "enabled": old_user.get("enabled"),
                "password_updated_at": old_user.get("password_updated_at")
            },
            "new": updated_user,
            "changed_fields": changed_fields
        }
    )

    conn.close()

    return {
        "status": "credentials_updated",
        "user": updated_user,
        "changed_fields": changed_fields
    }




def normalize_mac(mac: str) -> str:
    cleaned = re.sub(r"[^0-9A-Fa-f]", "", mac).lower()
    if len(cleaned) != 12:
        raise ValueError("chip_mac must contain exactly 12 hex characters")
    return cleaned


def normalize_eui(eui: str, expected_len: int) -> str:
    cleaned = re.sub(r"[^0-9A-Fa-f]", "", eui).upper()
    if len(cleaned) != expected_len:
        raise ValueError(f"EUI/key must contain exactly {expected_len} hex characters")
    return cleaned


def make_device_id(chip_mac: str) -> str:
    return f"node-{chip_mac}"


def generate_dev_eui() -> str:
    return secrets.token_hex(8).upper()


def generate_app_key() -> str:
    return secrets.token_hex(16).upper()


def validate_config() -> None:
    if not TTN_BASE or not APP_ID or not API_KEY:
        raise RuntimeError("TTN_BASE_URL, TTN_APP_ID, and TTN_API_KEY must be set in .env")
    normalize_eui(JOIN_EUI, 16)


def safe_json_or_text(resp: requests.Response):
    try:
        return resp.json()
    except Exception:
        return resp.text


def normalize_tb_value(value):
    if value in ["true", "True", True]:
        return True
    if value in ["false", "False", False]:
        return False

    try:
        return float(value)
    except Exception:
        return value


def get_existing_device(
    conn: sqlite3.Connection,
    chip_mac: str,
):
    """
    Return the complete device record.

    SELECT * is intentional here because the device table now
    contains profile, configuration and hierarchy columns in
    addition to the original legacy columns.
    """

    return conn.execute(
        """
        SELECT *
        FROM devices
        WHERE chip_mac = ?
        LIMIT 1
        """,
        (chip_mac,),
    ).fetchone()


def get_device_by_device_id(
    conn: sqlite3.Connection,
    device_id: str,
):
    """
    Return the complete device record by its public device ID.
    """

    return conn.execute(
        """
        SELECT *
        FROM devices
        WHERE device_id = ?
        LIMIT 1
        """,
        (device_id,),
    ).fetchone()

def get_room_from_database(conn: sqlite3.Connection, building: str, floor: str, room_name: str):
    cur = conn.execute("""
        SELECT id, floorplan_id, building, floor, room_name, x, y
        FROM rooms
        WHERE building = ?
        AND floor = ?
        AND room_name = ?
        LIMIT 1
    """, (building, floor, room_name))

    return cur.fetchone()

def get_room_by_id_for_provision(conn: sqlite3.Connection, room_id: int):
    row = conn.execute("""
        SELECT
            r.id AS room_id,
            r.room_name,
            r.building,
            r.floor,
            r.x,
            r.y,
            r.floor_id,
            f.building_id,
            b.site_id,
            s.client_id
        FROM rooms r
        LEFT JOIN floors f ON r.floor_id = f.id
        LEFT JOIN buildings b ON f.building_id = b.id
        LEFT JOIN sites s ON b.site_id = s.id
        WHERE r.id = ?
        LIMIT 1
    """, (room_id,)).fetchone()

    return row



def get_device_metadata_by_device_id(conn: sqlite3.Connection, device_id: str):
    return get_device_by_device_id(conn, device_id)


def dev_eui_exists(conn: sqlite3.Connection, dev_eui: str) -> bool:
    cur = conn.execute("SELECT 1 FROM devices WHERE dev_eui = ? LIMIT 1", (dev_eui,))
    return cur.fetchone() is not None


def generate_unique_dev_eui(conn: sqlite3.Connection) -> str:
    for _ in range(20):
        candidate = generate_dev_eui()
        if not dev_eui_exists(conn, candidate):
            return candidate
    raise RuntimeError("Failed to generate unique DevEUI")


def create_ttn_device_identity(device_id: str, dev_eui: str, join_eui: str) -> None:
    url = f"{TTN_BASE}/api/v3/applications/{APP_ID}/devices"

    payload = {
        "end_device": {
            "ids": {
                "device_id": device_id,
                "application_ids": {"application_id": APP_ID},
                "dev_eui": dev_eui,
                "join_eui": join_eui,
            },
            "name": device_id,
            "description": "Provisioned by Raspberry Pi backend",
            "network_server_address": TTN_HOST,
            "application_server_address": TTN_HOST,
            "join_server_address": TTN_HOST,
        },
        "field_mask": {
            "paths": [
                "ids.device_id",
                "ids.application_ids.application_id",
                "ids.dev_eui",
                "ids.join_eui",
                "name",
                "description",
                "network_server_address",
                "application_server_address",
                "join_server_address",
            ]
        },
    }

    resp = requests.post(url, headers=HEADERS, json=payload, timeout=20)

    if resp.status_code >= 300:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": "identity_create",
                "status_code": resp.status_code,
                "response": safe_json_or_text(resp),
            },
        )


