LIVE_TELEMETRY_SYSTEM_KEYS = (
    "alarm_active",
    "alarm_message",

    "battery_percent",
    "battery_voltage",
    "battery_status",
    "power_source",

    "signal_status",
    "gateway_id",
    "rssi",
    "snr",
    "spreading_factor",
    "bandwidth",
    "frequency",
    "received_by_gateways",

    "profile_code",
    "profile_version",
    "payload_version",
    "firmware_version",
    "node_type",

    "profile_alarm_active_count",
    "profile_alarm_rule_codes",
)


def load_device_profile_for_live_telemetry(
    conn: sqlite3.Connection,
    device_id: str,
):
    """
    Load the sensor profile assigned to a device for portal and
    ThingsBoard telemetry rendering.
    """

    clean_device_id = str(
        device_id or ""
    ).strip()

    if not clean_device_id:
        return None

    device_row = conn.execute(
        """
        SELECT
            profile_id,
            profile_code
        FROM devices
        WHERE device_id = ?
        LIMIT 1
        """,
        (clean_device_id,),
    ).fetchone()

    if not device_row:
        return None

    device = dict(device_row)

    profile_identifier = (
        device.get("profile_id")
        or device.get("profile_code")
    )

    if not profile_identifier:
        return None

    try:
        return get_sensor_profile_detail(
            conn,
            profile_identifier,
            include_formatter=False,
        )

    except Exception as exc:
        print(
            "Live telemetry profile lookup failed:",
            exc,
        )

        return None


def build_profile_live_field_metadata(
    profile: dict | None,
    surface: str = "all",
):
    """
    Return ordered telemetry-field metadata for portal rendering.

    surface:
        all       -> every profile field
        floor     -> fields enabled for Floor Live View
        dashboard -> fields enabled for dashboards
    """

    if not isinstance(profile, dict):
        return []

    clean_surface = str(
        surface or "all"
    ).strip().lower()

    result = []

    for field in profile.get(
        "fields",
        [],
    ):
        field_key = str(
            field.get("field_key") or ""
        ).strip()

        if not field_key:
            continue

        if (
            clean_surface == "floor"
            and not bool(
                field.get("visible_floor")
            )
        ):
            continue

        if (
            clean_surface == "dashboard"
            and not bool(
                field.get("visible_dashboard")
            )
        ):
            continue

        result.append(
            {
                "field_key": field_key,

                "label": (
                    field.get("label")
                    or field_key.replace(
                        "_",
                        " ",
                    ).title()
                ),

                "unit": field.get("unit"),

                "data_type": (
                    field.get("data_type")
                    or "number"
                ),

                "display_order": int(
                    field.get("display_order")
                    or 0
                ),

                "precision_digits": (
                    field.get(
                        "precision_digits"
                    )
                ),

                "min_value": field.get(
                    "min_value"
                ),

                "max_value": field.get(
                    "max_value"
                ),

                "visible_floor": bool(
                    field.get("visible_floor")
                ),

                "visible_dashboard": bool(
                    field.get(
                        "visible_dashboard"
                    )
                ),
            }
        )

    result.sort(
        key=lambda field: (
            field["display_order"],
            field["field_key"],
        )
    )

    return result


def build_profile_live_metadata(
    profile: dict | None,
):
    """
    Build the profile metadata returned to the device and floor
    portals.
    """

    if not isinstance(profile, dict):
        return None

    return {
        "profile_id": profile.get("id"),

        "profile_code": profile.get(
            "profile_code"
        ),

        "profile_name": profile.get(
            "profile_name"
        ),

        "profile_version": profile.get(
            "profile_version"
        ),

        "payload_version": profile.get(
            "payload_version"
        ),

        "node_type": profile.get(
            "node_type"
        ),

        "capabilities": (
            profile_unique_string_list(
                profile.get(
                    "capabilities",
                    [],
                )
            )
        ),

        "icon_type": profile.get(
            "icon_type"
        ),

        "icon_color": profile.get(
            "icon_color"
        ),

        "tb_device_profile_name": (
            profile.get(
                "tb_device_profile_name"
            )
        ),
    }


def get_profile_telemetry_keys(
    profile: dict | None,
):
    """
    Combine dynamic sensor fields with system telemetry fields.
    """

    keys = []

    for field in build_profile_live_field_metadata(
        profile,
        surface="all",
    ):
        field_key = field["field_key"]

        if field_key not in keys:
            keys.append(
                field_key
            )

    for system_key in (
        LIVE_TELEMETRY_SYSTEM_KEYS
    ):
        if system_key not in keys:
            keys.append(
                system_key
            )

    return keys



def read_tb_latest_telemetry(
    device_id: str,
    profile: dict | None = None,
):
    """
    Read ThingsBoard telemetry using keys declared by the assigned
    sensor profile instead of a fixed sensor-type list.

    Passing profile is optional to preserve compatibility with
    existing callers.
    """

    clean_device_id = str(
        device_id or ""
    ).strip()

    telemetry = {
        "alarm_active": False,
        "alarm_message": "OK",

        "last_seen_ts": None,
        "last_seen_iso": None,
        "last_seen_seconds_ago": None,

        "device_status": "offline",
    }

    # ---------------------------------------------------------
    # Load the assigned profile when it was not supplied
    # ---------------------------------------------------------

    if profile is None and clean_device_id:
        profile_conn = None

        try:
            profile_conn = db()

            profile = (
                load_device_profile_for_live_telemetry(
                    profile_conn,
                    clean_device_id,
                )
            )

        except Exception as exc:
            print(
                "ThingsBoard profile lookup failed:",
                exc,
            )

            profile = None

        finally:
            if profile_conn is not None:
                profile_conn.close()

    telemetry_fields = (
        build_profile_live_field_metadata(
            profile,
            surface="all",
        )
    )

    # Ensure every profile field exists even when ThingsBoard
    # has not received its first value yet.
    for field in telemetry_fields:
        telemetry.setdefault(
            field["field_key"],
            None,
        )

    requested_keys = (
        get_profile_telemetry_keys(
            profile
        )
    )

    if not clean_device_id:
        return telemetry

    tb_device = tb_get_device_by_name(
        clean_device_id
    )

    if not tb_device:
        return telemetry

    try:
        tb_id = tb_device["id"]["id"]

    except Exception:
        print(
            "ThingsBoard device has no valid ID:",
            clean_device_id,
        )

        return telemetry

    try:
        response = tb_request(
            "GET",
            (
                "/api/plugins/telemetry/"
                f"DEVICE/{tb_id}/values/timeseries"
            ),
            params={
                "keys": ",".join(
                    requested_keys
                )
            },
        )

    except Exception as exc:
        print(
            "ThingsBoard telemetry read failed:",
            exc,
        )

        return telemetry

    try:
        data = response.json()

        if not isinstance(data, dict):
            data = {}

    except Exception:
        data = {}

    latest_ts = None

    for key in requested_keys:
        values = data.get(key)

        if (
            not isinstance(values, list)
            or not values
        ):
            continue

        latest_item = values[0]

        if not isinstance(
            latest_item,
            dict,
        ):
            continue

        telemetry[key] = normalize_tb_value(
            latest_item.get("value")
        )

        timestamp = latest_item.get(
            "ts"
        )

        if timestamp is not None:
            try:
                timestamp = int(
                    timestamp
                )

                if (
                    latest_ts is None
                    or timestamp > latest_ts
                ):
                    latest_ts = timestamp

            except Exception:
                pass

    if latest_ts is not None:
        import time

        now_ms = int(
            time.time() * 1000
        )

        seconds_ago = max(
            0,
            int(
                (
                    now_ms
                    - latest_ts
                )
                / 1000
            ),
        )

        telemetry["last_seen_ts"] = (
            latest_ts
        )

        telemetry["last_seen_iso"] = (
            datetime.fromtimestamp(
                latest_ts / 1000,
                tz=timezone.utc,
            ).isoformat()
        )

        telemetry[
            "last_seen_seconds_ago"
        ] = seconds_ago

        telemetry["device_status"] = (
            "online"
            if seconds_ago <= 300
            else "offline"
        )

    return telemetry




