def ttn_get_gateway_status(gateway_id: str):
    url = f"{TTN_BASE}/api/v3/gateways/{gateway_id}"

    r = requests.get(
        url,
        headers=HEADERS,
        timeout=20
    )

    if r.status_code >= 300:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": "ttn_gateway_status",
                "status_code": r.status_code,
                "response": safe_json_or_text(r),
            },
        )

    data = r.json()

    return data
    
@app.get("/gateways/{gateway_id}/sync")
def sync_gateway_status(gateway_id: str):
    gateway_record = ttn_get_gateway_status(gateway_id)
    connection_stats = ttn_get_gateway_connection_stats(gateway_id)

    if connection_stats:
        status = "online"
        last_seen = connection_stats.get("connected_at")
    else:
        status = "offline"
        last_seen = None

    conn = db()

    conn.execute("""
        UPDATE gateways
        SET status = ?,
            last_seen = ?
        WHERE gateway_id = ?
    """, (
        status,
        last_seen,
        gateway_id,
    ))

    conn.commit()

    row = conn.execute("""
        SELECT *
        FROM gateways
        WHERE gateway_id = ?
    """, (gateway_id,)).fetchone()

    conn.close()

    if not row:
        raise HTTPException(
            status_code=404,
            detail="Gateway not found in backend database"
        )

    return {
        "status": "synced",
        "gateway": dict(row),
        "gateway_health": {
            "connection_status": status,
            "connected_at": last_seen,
            "stats": connection_stats
        },
        "ttn_gateway_record": gateway_record,
    }

@app.get("/gateways/health")
def gateways_health(site_id: int | None = None):
    conn = db()

    if site_id is not None:
        rows = conn.execute("""
            SELECT *
            FROM gateways
            WHERE site_id = ?
            ORDER BY name
        """, (site_id,)).fetchall()
    else:
        rows = conn.execute("""
            SELECT *
            FROM gateways
            ORDER BY name
        """).fetchall()

    result = []

    for row in rows:
        gateway_id = row["gateway_id"]

        try:
            connection_stats = ttn_get_gateway_connection_stats(gateway_id)

            if connection_stats:
                connection_status = "online"

                last_seen = (
                    connection_stats.get("last_status_received_at")
                    or connection_stats.get("last_uplink_received_at")
                    or connection_stats.get("connected_at")
                )

                protocol = connection_stats.get("protocol")
                last_status_received_at = connection_stats.get("last_status_received_at")
                last_uplink_received_at = connection_stats.get("last_uplink_received_at")
                last_downlink_received_at = connection_stats.get("last_downlink_received_at")
                uplink_count = connection_stats.get("uplink_count")
                downlink_count = connection_stats.get("downlink_count")

                ip = None

                remote_address = connection_stats.get("gateway_remote_address")
                if remote_address:
                    ip = remote_address.get("ip")

                if not ip:
                    last_status = connection_stats.get("last_status", {})
                    ip_list = last_status.get("ip", [])
                    if ip_list:
                        ip = ip_list[0]

                error_message = None

            else:
                connection_status = "offline"
                last_seen = None
                protocol = None
                last_status_received_at = None
                last_uplink_received_at = None
                last_downlink_received_at = None
                uplink_count = 0
                downlink_count = 0
                ip = None
                error_message = None

        except HTTPException as e:
            connection_status = "error"
            last_seen = None
            protocol = None
            last_status_received_at = None
            last_uplink_received_at = None
            last_downlink_received_at = None
            uplink_count = 0
            downlink_count = 0
            ip = None
            error_message = str(e.detail)

        conn.execute("""
            UPDATE gateways
            SET status = ?,
                last_seen = ?
            WHERE gateway_id = ?
        """, (
            connection_status,
            last_seen,
            gateway_id
        ))

        result.append({
            "id": row["id"],
            "gateway_id": gateway_id,
            "name": row["name"],
            "client_id": row["client_id"],
            "site_id": row["site_id"],
            "connection_status": connection_status,
            "last_seen": last_seen,
            "last_status_received_at": last_status_received_at,
            "last_uplink_received_at": last_uplink_received_at,
            "last_downlink_received_at": last_downlink_received_at,
            "uplink_count": uplink_count,
            "downlink_count": downlink_count,
            "protocol": protocol,
            "ip": ip,
            "error_message": error_message
        })

    conn.commit()
    conn.close()

    return result


def ttn_get_gateway_connection_stats(gateway_id: str):
    url = f"{TTN_BASE}/api/v3/gs/gateways/{gateway_id}/connection/stats"

    r = requests.get(
        url,
        headers=HEADERS,
        timeout=20
    )

    if r.status_code == 404:
        return None

    if r.status_code >= 300:
        raise HTTPException(
            status_code=502,
            detail={
                "stage": "ttn_gateway_connection_stats",
                "status_code": r.status_code,
                "response": safe_json_or_text(r),
            },
        )

    return r.json()
    
