@app.get("/sensor-catalog")
def sensor_catalog_api(
    include_disabled: bool = True,
):
    """
    Return physical and compatibility sensors registered in
    the sensor catalog.
    """

    conn = db()

    try:
        sql = """
            SELECT
                catalog.id,
                catalog.sensor_code,
                catalog.manufacturer,
                catalog.model,
                catalog.use_case,
                catalog.protocol,
                catalog.default_bus,
                catalog.default_address,
                catalog.datasheet_url,
                catalog.description,
                catalog.enabled,
                catalog.created_at,
                catalog.updated_at,

                COUNT(
                    DISTINCT relation.profile_id
                ) AS profile_count

            FROM sensor_catalog catalog

            LEFT JOIN sensor_profile_sensors relation
                ON relation.sensor_id = catalog.id
        """

        parameters = []

        if not include_disabled:
            sql += """
                WHERE catalog.enabled = 1
            """

        sql += """
            GROUP BY catalog.id

            ORDER BY
                catalog.use_case,
                catalog.manufacturer,
                catalog.model
        """

        rows = conn.execute(
            sql,
            parameters,
        ).fetchall()

        sensors = []

        for row in rows:
            sensor = dict(row)
            sensor["enabled"] = bool(
                sensor.get("enabled")
            )
            sensors.append(sensor)

        return {
            "status": "ok",
            "count": len(sensors),
            "sensors": sensors,
        }

    finally:
        conn.close()


@app.get("/firmware-modules")
def firmware_modules_api(
    include_disabled: bool = True,
):
    """
    Return the firmware drivers/modules supported by profiles.
    """

    conn = db()

    try:
        sql = """
            SELECT
                module.id,
                module.module_key,
                module.display_name,
                module.driver_class,
                module.protocol,
                module.library_name,
                module.library_version,
                module.supported_board,
                module.min_firmware_version,
                module.source_file,
                module.notes,
                module.enabled,
                module.created_at,
                module.updated_at,

                COUNT(
                    DISTINCT relation.profile_id
                ) AS profile_count

            FROM firmware_modules module

            LEFT JOIN sensor_profile_sensors relation
                ON relation.firmware_module_id = module.id
        """

        parameters = []

        if not include_disabled:
            sql += """
                WHERE module.enabled = 1
            """

        sql += """
            GROUP BY module.id

            ORDER BY module.display_name
        """

        rows = conn.execute(
            sql,
            parameters,
        ).fetchall()

        modules = []

        for row in rows:
            module = dict(row)
            module["enabled"] = bool(
                module.get("enabled")
            )

            profile_rows = conn.execute(
                """
                SELECT DISTINCT profile_id
                FROM (
                    SELECT profile_id
                    FROM sensor_profile_sensors
                    WHERE firmware_module_id = ?

                    UNION

                    SELECT profile_id
                    FROM profile_firmware_compatibility
                    WHERE firmware_module_id = ?
                )
                """,
                (module["id"], module["id"]),
            ).fetchall()

            module["profile_count"] = len(profile_rows)
            module["can_delete"] = (
                module["profile_count"] == 0
            )

            modules.append(module)

        return {
            "status": "ok",
            "count": len(modules),
            "modules": modules,
        }

    finally:
        conn.close()

