# SENSOR PROFILE WRITE API
# =============================================================

def sensor_profile_actor_from_request(
    request: Request,
) -> str:
    """
    Resolve the administrator responsible for a profile change.
    """

    try:
        user = get_current_user_from_request(request)
    except Exception:
        user = None

    if not user:
        return "admin_api"

    return str(
        user.get("email")
        or user.get("username")
        or user.get("name")
        or user.get("id")
        or "admin_api"
    )


# =============================================================
# SENSOR CATALOG WRITE SERVICE AND API
# =============================================================

def normalize_sensor_catalog_definition(
    conn: sqlite3.Connection,
    data: dict,
    exclude_sensor_id: int | None = None,
):
    """
    Validate and normalize one physical-sensor catalog record.

    Sensor catalog records describe hardware supported by firmware.
    They do not install Arduino libraries or alter firmware binaries.
    """

    if not isinstance(data, dict):
        raise ValueError("Sensor definition must be a JSON object")

    sensor_code = str(
        data.get("sensor_code") or ""
    ).strip().upper()

    manufacturer = str(
        data.get("manufacturer") or ""
    ).strip()

    model = str(
        data.get("model") or ""
    ).strip()

    use_case = str(
        data.get("use_case") or ""
    ).strip().lower()

    protocol = str(
        data.get("protocol") or ""
    ).strip().lower()

    default_bus = str(
        data.get("default_bus") or ""
    ).strip()

    default_address = str(
        data.get("default_address") or ""
    ).strip()

    datasheet_url = str(
        data.get("datasheet_url") or ""
    ).strip()

    description = str(
        data.get("description") or ""
    ).strip()

    enabled = profile_value_to_boolean(
        data.get("enabled", True),
        default=True,
    )

    errors = []

    if not PROFILE_CODE_PATTERN.fullmatch(sensor_code):
        errors.append(
            "sensor_code must start with an uppercase letter and "
            "contain only A-Z, 0-9 and underscores"
        )

    if not model:
        errors.append("model is required")

    if len(model) > 120:
        errors.append("model must not exceed 120 characters")

    if manufacturer and len(manufacturer) > 120:
        errors.append("manufacturer must not exceed 120 characters")

    if not PROFILE_KEY_PATTERN.fullmatch(use_case):
        errors.append(
            "use_case must start with a lowercase letter and contain "
            "only lowercase letters, numbers and underscores"
        )

    if not PROFILE_KEY_PATTERN.fullmatch(protocol):
        errors.append(
            "protocol must start with a lowercase letter and contain "
            "only lowercase letters, numbers and underscores"
        )

    if datasheet_url and not datasheet_url.lower().startswith(
        ("http://", "https://")
    ):
        errors.append(
            "datasheet_url must start with http:// or https://"
        )

    duplicate_sql = """
        SELECT id
        FROM sensor_catalog
        WHERE UPPER(sensor_code) = UPPER(?)
    """

    duplicate_parameters = [sensor_code]

    if exclude_sensor_id is not None:
        duplicate_sql += " AND id != ?"
        duplicate_parameters.append(exclude_sensor_id)

    duplicate_sql += " LIMIT 1"

    if sensor_code and conn.execute(
        duplicate_sql,
        duplicate_parameters,
    ).fetchone():
        errors.append(
            f"sensor_code already exists: {sensor_code}"
        )

    if errors:
        raise ValueError("; ".join(errors))

    return {
        "sensor_code": sensor_code,
        "manufacturer": manufacturer or None,
        "model": model,
        "use_case": use_case,
        "protocol": protocol,
        "default_bus": default_bus or None,
        "default_address": default_address or None,
        "datasheet_url": datasheet_url or None,
        "description": description or None,
        "enabled": enabled,
    }


def get_sensor_catalog_detail(
    conn: sqlite3.Connection,
    sensor_id: int,
):
    """Return one sensor catalog record with profile usage count."""

    row = conn.execute(
        """
        SELECT
            catalog.*,
            COUNT(DISTINCT relation.profile_id) AS profile_count
        FROM sensor_catalog catalog
        LEFT JOIN sensor_profile_sensors relation
            ON relation.sensor_id = catalog.id
        WHERE catalog.id = ?
        GROUP BY catalog.id
        LIMIT 1
        """,
        (sensor_id,),
    ).fetchone()

    if not row:
        return None

    sensor = dict(row)
    sensor["enabled"] = bool(sensor.get("enabled"))
    sensor["can_delete"] = int(
        sensor.get("profile_count") or 0
    ) == 0

    return sensor


