@app.post(
    "/firmware-modules",
    status_code=201,
)
def create_firmware_module_api(
    request: Request,
    module_definition: dict,
):
    """Register a driver already available in a firmware build."""

    conn = db()

    try:
        actor = sensor_profile_actor_from_request(request)

        normalized = normalize_firmware_module_definition(
            conn,
            module_definition,
        )

        now = profile_utc_now_iso()

        cursor = conn.execute(
            """
            INSERT INTO firmware_modules(
                module_key,
                display_name,
                driver_class,
                protocol,
                library_name,
                library_version,
                supported_board,
                min_firmware_version,
                source_file,
                notes,
                enabled,
                created_at,
                updated_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                normalized["module_key"],
                normalized["display_name"],
                normalized["driver_class"],
                normalized["protocol"],
                normalized["library_name"],
                normalized["library_version"],
                normalized["supported_board"],
                normalized["min_firmware_version"],
                normalized["source_file"],
                normalized["notes"],
                int(normalized["enabled"]),
                now,
                now,
            ),
        )

        module_id = int(cursor.lastrowid)
        conn.commit()

        module = get_firmware_module_detail(
            conn,
            module_id,
        )

        log_audit_event(
            conn,
            action="create_firmware_module",
            actor=actor,
            target_type="firmware_module",
            target_id=module_id,
            details={"module": module},
            message=(
                "Firmware module registered: "
                + normalized["module_key"]
            ),
        )

        return {
            "status": "created",
            "message": "Firmware module registered",
            "module": module,
        }

    except ValueError as error:
        conn.rollback()
        raise HTTPException(
            status_code=400,
            detail=str(error),
        )

    except sqlite3.IntegrityError as error:
        conn.rollback()
        raise HTTPException(
            status_code=409,
            detail=(
                "The firmware module conflicts with an existing record: "
                + str(error)
            ),
        )

    except HTTPException:
        conn.rollback()
        raise

    except Exception as error:
        conn.rollback()
        print("Create firmware module error:", error)
        raise HTTPException(
            status_code=500,
            detail="Could not register the firmware module",
        )

    finally:
        conn.close()


@app.put("/firmware-modules/{module_id}")
def update_firmware_module_api(
    module_id: int,
    request: Request,
    module_definition: dict,
):
    """Update one registered firmware module."""

    conn = db()

    try:
        existing = get_firmware_module_detail(
            conn,
            module_id,
        )

        if not existing:
            raise HTTPException(
                status_code=404,
                detail="Firmware module not found",
            )

        actor = sensor_profile_actor_from_request(request)

        normalized = normalize_firmware_module_definition(
            conn,
            module_definition,
            exclude_module_id=module_id,
        )

        conn.execute(
            """
            UPDATE firmware_modules
            SET
                module_key = ?,
                display_name = ?,
                driver_class = ?,
                protocol = ?,
                library_name = ?,
                library_version = ?,
                supported_board = ?,
                min_firmware_version = ?,
                source_file = ?,
                notes = ?,
                enabled = ?,
                updated_at = ?
            WHERE id = ?
            """,
            (
                normalized["module_key"],
                normalized["display_name"],
                normalized["driver_class"],
                normalized["protocol"],
                normalized["library_name"],
                normalized["library_version"],
                normalized["supported_board"],
                normalized["min_firmware_version"],
                normalized["source_file"],
                normalized["notes"],
                int(normalized["enabled"]),
                profile_utc_now_iso(),
                module_id,
            ),
        )

        conn.commit()

        module = get_firmware_module_detail(
            conn,
            module_id,
        )

        log_audit_event(
            conn,
            action="update_firmware_module",
            actor=actor,
            target_type="firmware_module",
            target_id=module_id,
            details={
                "old": existing,
                "new": module,
            },
            message=(
                "Firmware module updated: "
                + normalized["module_key"]
            ),
        )

        return {
            "status": "updated",
            "message": "Firmware module updated",
            "module": module,
        }

    except ValueError as error:
        conn.rollback()
        raise HTTPException(
            status_code=400,
            detail=str(error),
        )

    except sqlite3.IntegrityError as error:
        conn.rollback()
        raise HTTPException(
            status_code=409,
            detail=(
                "The firmware-module update conflicts with another record: "
                + str(error)
            ),
        )

    except HTTPException:
        conn.rollback()
        raise

    except Exception as error:
        conn.rollback()
        print("Update firmware module error:", error)
        raise HTTPException(
            status_code=500,
            detail="Could not update the firmware module",
        )

    finally:
        conn.close()


def set_firmware_module_enabled_api(
    module_id: int,
    request: Request,
    enabled: bool,
):
    """Enable or disable a firmware module without deleting history."""

    conn = db()

    try:
        module = get_firmware_module_detail(
            conn,
            module_id,
        )

        if not module:
            raise HTTPException(
                status_code=404,
                detail="Firmware module not found",
            )

        actor = sensor_profile_actor_from_request(request)

        conn.execute(
            """
            UPDATE firmware_modules
            SET enabled = ?, updated_at = ?
            WHERE id = ?
            """,
            (
                int(enabled),
                profile_utc_now_iso(),
                module_id,
            ),
        )

        conn.commit()

        updated_module = get_firmware_module_detail(
            conn,
            module_id,
        )

        action = (
            "enable_firmware_module"
            if enabled
            else "disable_firmware_module"
        )

        log_audit_event(
            conn,
            action=action,
            actor=actor,
            target_type="firmware_module",
            target_id=module_id,
            details={"module": updated_module},
            message=(
                ("Enabled" if enabled else "Disabled")
                + " firmware module: "
                + str(updated_module.get("module_key"))
            ),
        )

        return {
            "status": "enabled" if enabled else "disabled",
            "message": (
                "Firmware module enabled"
                if enabled
                else "Firmware module disabled"
            ),
            "module": updated_module,
        }

    except HTTPException:
        conn.rollback()
        raise

    except Exception as error:
        conn.rollback()
        print("Firmware module status error:", error)
        raise HTTPException(
            status_code=500,
            detail="Could not change firmware module status",
        )

    finally:
        conn.close()


