@app.post(
    "/sensor-profiles/{profile_id}/clone",
    status_code=201,
)
def clone_sensor_profile_api(
    profile_id: int,
    request: Request,
    clone_request: dict,
):
    """
    Clone a profile using either the advanced clone workflow
    or the simplified administrator workflow.
    """

    conn = db()

    try:
        actor = sensor_profile_actor_from_request(
            request
        )

        new_profile_name = str(
            clone_request.get(
                "new_profile_name",
                "",
            )
        ).strip()

        if not new_profile_name:
            raise ValueError(
                "new_profile_name is required"
            )

        new_profile_code = str(
            clone_request.get(
                "new_profile_code",
                "",
            )
        ).strip().upper()

        if not new_profile_code:
            new_profile_code = (
                generate_unique_sensor_profile_code(
                    conn,
                    new_profile_name,
                )
            )

        activate = profile_value_to_boolean(
            clone_request.get(
                "activate",
                False,
            ),
            default=False,
        )

        uplink_interval_seconds = (
            clone_request.get(
                "uplink_interval_seconds"
            )
        )

        alarm_thresholds = (
            clone_request.get(
                "alarm_thresholds",
                {},
            )
        )

        cloned_profile = (
            clone_sensor_profile_record(
                conn,
                profile_id,
                new_profile_code,
                new_profile_name,
                actor=actor,
                activate=activate,
                uplink_interval_seconds=(
                    uplink_interval_seconds
                ),
                alarm_thresholds=(
                    alarm_thresholds
                ),
            )
        )

        conn.commit()

        return {
            "status": (
                "created"
                if activate
                else "cloned"
            ),
            "message": (
                "Sensor profile created and activated"
                if activate
                else "Sensor profile cloned"
            ),
            "source_profile_id": profile_id,
            "generated_profile_code": (
                new_profile_code
            ),
            "profile": cloned_profile,
        }

    except ValueError as error:
        conn.rollback()

        error_message = str(error)
        lower_error = error_message.lower()

        if "not found" in lower_error:
            status_code = 404

        elif (
            "already exists" in lower_error
            or "conflicts" in lower_error
        ):
            status_code = 409

        else:
            status_code = 400

        raise HTTPException(
            status_code=status_code,
            detail=error_message,
        )

    except sqlite3.IntegrityError as error:
        conn.rollback()

        raise HTTPException(
            status_code=409,
            detail=(
                "The requested profile code already "
                "exists or conflicts with another record: "
                + str(error)
            ),
        )

    except HTTPException:
        conn.rollback()
        raise

    except Exception as error:
        conn.rollback()

        print(
            "Clone sensor profile API error:",
            error,
        )

        raise HTTPException(
            status_code=500,
            detail=(
                "Could not clone the sensor profile"
            ),
        )

    finally:
        conn.close()




