@app.put("/users/{user_id}")
def update_user(user_id: int, data: dict):
    conn = db()

    row = conn.execute("""
        SELECT *
        FROM users
        WHERE id = ?
    """, (user_id,)).fetchone()

    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="User not found")

    old_user = dict(row)

    name = data.get("name", row["name"])
    email = data.get("email", row["email"]).strip().lower()
    role = data.get("role", row["role"])
    enabled = data.get("enabled", row["enabled"])

    try:
        conn.execute("""
            UPDATE users
            SET name = ?,
                email = ?,
                role = ?,
                enabled = ?
            WHERE id = ?
        """, (
            name,
            email,
            role,
            enabled,
            user_id
        ))

        conn.commit()

        updated = conn.execute("""
            SELECT *
            FROM users
            WHERE id = ?
        """, (user_id,)).fetchone()

        log_audit_event(
            conn,
            action="update_user",
            target_type="user",
            target_id=user_id,
            details={
                "old": old_user,
                "new": dict(updated)
            }
        )

        conn.close()

        return {
            "status": "updated",
            "user": dict(updated)
        }

    except sqlite3.IntegrityError:
        conn.close()
        raise HTTPException(status_code=400, detail="User email already exists")


