@app.delete("/users/{user_id}")
def delete_user(user_id: int):
    conn = db()

    row = conn.execute("""
        SELECT *
        FROM users
        WHERE id = ?
    """, (user_id,)).fetchone()

    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="User not found")

    deleted_user = dict(row)

    access_rows = conn.execute("""
        SELECT *
        FROM user_access
        WHERE user_id = ?
    """, (user_id,)).fetchall()

    deleted_access_records = [dict(a) for a in access_rows]

    conn.execute("""
        DELETE FROM user_access
        WHERE user_id = ?
    """, (user_id,))

    conn.execute("""
        DELETE FROM users
        WHERE id = ?
    """, (user_id,))

    conn.commit()

    log_audit_event(
        conn,
        action="delete_user",
        target_type="user",
        target_id=user_id,
        details={
            "deleted_user": deleted_user,
            "deleted_access_records": deleted_access_records
        }
    )

    conn.close()

    return {
        "status": "deleted",
        "user_id": user_id,
        "deleted_access_records": True
    }

@app.post("/user-access")
def create_user_access(data: dict):
    user_id = data.get("user_id")
    client_id = data.get("client_id")
    site_id = data.get("site_id")
    building_id = data.get("building_id")
    floor_id = data.get("floor_id")

    access_level = data.get("access_level", "viewer")

    can_view_devices = data.get("can_view_devices", 1)
    can_view_gateways = data.get("can_view_gateways", 1)
    can_view_alarms = data.get("can_view_alarms", 1)
    can_view_telemetry = data.get("can_view_telemetry", 1)
    can_manage_email_settings = data.get("can_manage_email_settings", 0)

    if not user_id:
        raise HTTPException(status_code=400, detail="user_id is required")

    if not client_id and not site_id and not building_id and not floor_id:
        raise HTTPException(
            status_code=400,
            detail="At least one access scope is required: client_id, site_id, building_id, or floor_id"
        )

    conn = db()

    user = conn.execute("""
        SELECT *
        FROM users
        WHERE id = ?
    """, (user_id,)).fetchone()

    if not user:
        conn.close()
        raise HTTPException(status_code=404, detail="User not found")

    existing = conn.execute("""
        SELECT *
        FROM user_access
        WHERE user_id = ?
          AND IFNULL(client_id, 0) = IFNULL(?, 0)
          AND IFNULL(site_id, 0) = IFNULL(?, 0)
          AND IFNULL(building_id, 0) = IFNULL(?, 0)
          AND IFNULL(floor_id, 0) = IFNULL(?, 0)
    """, (
        user_id,
        client_id,
        site_id,
        building_id,
        floor_id
    )).fetchone()

    if existing:
        conn.close()
        return {
            "status": "already_exists",
            "access": dict(existing)
        }

    cur = conn.execute("""
        INSERT INTO user_access(
            user_id,
            client_id,
            site_id,
            building_id,
            floor_id,
            access_level,
            can_view_devices,
            can_view_gateways,
            can_view_alarms,
            can_view_telemetry,
            can_manage_email_settings
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        user_id,
        client_id,
        site_id,
        building_id,
        floor_id,
        access_level,
        can_view_devices,
        can_view_gateways,
        can_view_alarms,
        can_view_telemetry,
        can_manage_email_settings
    ))

    conn.commit()

    access_id = cur.lastrowid

    row = conn.execute("""
        SELECT *
        FROM user_access
        WHERE id = ?
    """, (access_id,)).fetchone()

    log_audit_event(
        conn,
        action="create_user_access",
        target_type="user_access",
        target_id=access_id,
        details={
            "user": {
                "id": user["id"],
                "name": user["name"],
                "email": user["email"]
            },
            "access": dict(row)
        }
    )

    conn.close()

    return {
        "status": "created",
        "access": dict(row)
    }


