def parse_datetime_safe(value):
    if not value:
        return None

    try:
        text = str(value).strip()

        if text.endswith("Z"):
            text = text[:-1] + "+00:00"

        try:
            dt = datetime.fromisoformat(text)
        except Exception:
            dt = datetime.strptime(text, "%Y-%m-%d %H:%M:%S")

        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)

        return dt

    except Exception:
        return None
    
    
@app.get("/floors/{floor_id}/live")
def get_floor_live(floor_id: int):
    """
    Return one floor with rooms, gateways and profile-driven
    device telemetry for Floor Live View.
    """

    conn = db()

    try:
        # =====================================================
        # 1. LOAD FLOOR
        # =====================================================

        floor = conn.execute(
            """
            SELECT
                f.*,
                b.name AS building_name
            FROM floors AS f
            LEFT JOIN buildings AS b
              ON b.id = f.building_id
            WHERE f.id = ?
            """,
            (floor_id,),
        ).fetchone()

        if not floor:
            raise HTTPException(
                status_code=404,
                detail="Floor not found",
            )

        floor_dict = dict(
            floor
        )

        floor_name = floor_dict.get(
            "name"
        )

        floor_number = floor_dict.get(
            "floor_number"
        )

        building_name = floor_dict.get(
            "building_name"
        )

        # =====================================================
        # 2. LOAD FLOOR ROOMS
        # =====================================================

        rooms = conn.execute(
            """
            SELECT *
            FROM rooms
            WHERE floor_id = ?

               OR floorplan_id IN (
                    SELECT id
                    FROM floorplans
                    WHERE floor_id = ?
               )

               OR (
                    building = ?
                    AND (
                        floor = ?
                        OR floor = ?
                    )
               )

            ORDER BY room_name
            """,
            (
                floor_id,
                floor_id,
                building_name,
                floor_name,
                floor_number,
            ),
        ).fetchall()

        result = {
            "floor": floor_dict,
            "rooms": [],
            "gateways": [],
        }

        # =====================================================
        # 3. BUILD EVERY ROOM
        # =====================================================

        for room in rooms:
            room_obj = dict(
                room
            )

            try:
                room_obj["polygon_points"] = (
                    json.loads(
                        room_obj[
                            "polygon_points"
                        ]
                    )
                    if room_obj.get(
                        "polygon_points"
                    )
                    else []
                )

            except Exception:
                room_obj[
                    "polygon_points"
                ] = []

            devices = conn.execute(
                """
                SELECT DISTINCT *
                FROM devices
                WHERE room_id = ?

                   OR (
                        room = ?

                        AND (
                            floor_id = ?
                            OR floor = ?
                            OR floor = ?
                        )
                   )

                ORDER BY
                    COALESCE(label, device_id),
                    device_id
                """,
                (
                    room["id"],
                    room["room_name"],
                    floor_id,
                    floor_name,
                    floor_number,
                ),
            ).fetchall()

            room_obj["devices"] = []

            # =================================================
            # 4. BUILD EVERY DEVICE
            # =================================================

            for device_row in devices:
                device = dict(
                    device_row
                )

                device_id = device[
                    "device_id"
                ]

                # ---------------------------------------------
                # Assigned sensor profile
                # ---------------------------------------------

                profile = (
                    load_device_profile_for_live_telemetry(
                        conn,
                        device_id,
                    )
                )

                profile_metadata = (
                    build_profile_live_metadata(
                        profile
                    )
                )

                # ---------------------------------------------
                # Capabilities
                # ---------------------------------------------

                if profile_metadata:
                    capabilities = (
                        profile_metadata[
                            "capabilities"
                        ]
                    )

                else:
                    try:
                        capabilities = (
                            get_device_capabilities_list(
                                conn,
                                device_id,
                                device.get(
                                    "node_type"
                                ),
                            )
                        )

                    except Exception:
                        capabilities = [
                            device.get(
                                "node_type"
                            )
                        ]

                capabilities = [
                    capability
                    for capability in capabilities
                    if capability
                ]

                # ---------------------------------------------
                # ThingsBoard telemetry
                # ---------------------------------------------

                try:
                    tb_telemetry = (
                        read_tb_latest_telemetry(
                            device_id,
                            profile=profile,
                        )
                        or {}
                    )

                except Exception as exc:
                    print(
                        "ThingsBoard telemetry failed "
                        "in floor live:",
                        exc,
                    )

                    tb_telemetry = {}

                # ---------------------------------------------
                # Local validated telemetry
                # ---------------------------------------------

                try:
                    local_telemetry = (
                        get_local_latest_telemetry(
                            conn,
                            device_id,
                        )
                        or {}
                    )

                except Exception as exc:
                    print(
                        "Local telemetry failed "
                        "in floor live:",
                        exc,
                    )

                    local_telemetry = {}

                # ---------------------------------------------
                # Merge both sources
                # ---------------------------------------------

                telemetry = (
                    merge_profile_live_telemetry_sources(
                        tb_telemetry,
                        local_telemetry,
                    )
                )

                # All fields declared by the selected profile.
                telemetry_fields = (
                    build_profile_live_field_metadata(
                        profile,
                        surface="all",
                    )
                )

                # Only fields enabled for Floor Live View.
                floor_display_telemetry = (
                    build_profile_display_telemetry(
                        profile,
                        telemetry,
                        surface="floor",
                    )
                )

                # ---------------------------------------------
                # Build device response
                # ---------------------------------------------

                device["node_type"] = (
                    profile.get(
                        "node_type"
                    )
                    if profile
                    else device.get(
                        "node_type"
                    )
                )

                device["capabilities"] = (
                    capabilities
                )

                device["profile_assigned"] = (
                    bool(profile)
                )

                device["profile"] = (
                    profile_metadata
                )

                device["profile_id"] = (
                    profile.get("id")
                    if profile
                    else device.get(
                        "profile_id"
                    )
                )

                device["profile_code"] = (
                    profile.get(
                        "profile_code"
                    )
                    if profile
                    else device.get(
                        "profile_code"
                    )
                )

                device["profile_version"] = (
                    profile.get(
                        "profile_version"
                    )
                    if profile
                    else device.get(
                        "profile_version"
                    )
                )

                device["payload_version"] = (
                    profile.get(
                        "payload_version"
                    )
                    if profile
                    else device.get(
                        "payload_version"
                    )
                )

                device["icon_type"] = (
                    profile.get(
                        "icon_type"
                    )
                    if (
                        profile
                        and profile.get(
                            "icon_type"
                        )
                    )
                    else device.get(
                        "icon_type"
                    )
                )

                device["icon_color"] = (
                    profile.get(
                        "icon_color"
                    )
                    if profile
                    else None
                )

                device["telemetry"] = (
                    telemetry
                )

                device["telemetry_fields"] = (
                    telemetry_fields
                )

                device[
                    "display_telemetry"
                ] = floor_display_telemetry

                room_obj["devices"].append(
                    device
                )

            result["rooms"].append(
                room_obj
            )

        # =====================================================
        # 5. LOAD FLOOR GATEWAYS
        # =====================================================

        try:
            gateway_rows = conn.execute(
                """
                SELECT *
                FROM gateways
                WHERE floor_id = ?
                ORDER BY name
                """,
                (floor_id,),
            ).fetchall()

            result["gateways"] = [
                dict(gateway)
                for gateway in gateway_rows
            ]

        except Exception as exc:
            print(
                "Gateway loading failed "
                "in floor live:",
                exc,
            )

            result["gateways"] = []

        return result

    finally:
        conn.close()

@app.delete("/buildings/{building_id}/polygon")
def delete_building_polygon(building_id: int):
    conn = db()

    cur = conn.execute("""
        UPDATE buildings
        SET polygon_points = ?,
            x = NULL,
            y = NULL
        WHERE id = ?
    """, (
        json.dumps([]),
        building_id,
    ))

    conn.commit()
    updated = cur.rowcount
    conn.close()

    if updated == 0:
        raise HTTPException(status_code=404, detail="Building not found")

    return {
        "status": "polygon_deleted",
        "building_id": building_id,
    }

