@app.delete("/rooms/{room_id}")
def delete_room(room_id: int):
    conn = db()

    room = conn.execute("""
        SELECT *
        FROM rooms
        WHERE id = ?
    """, (room_id,)).fetchone()

    if not room:
        conn.close()
        raise HTTPException(
            status_code=404,
            detail="Room not found"
        )

    devices_count = conn.execute("""
        SELECT COUNT(*)
        FROM devices
        WHERE room_id = ?
    """, (room_id,)).fetchone()[0]

    conn.execute("""
        UPDATE devices
        SET room_id = NULL,
            room = NULL,
            x = NULL,
            y = NULL
        WHERE room_id = ?
    """, (room_id,))

    conn.execute("""
        DELETE FROM rooms
        WHERE id = ?
    """, (room_id,))

    conn.commit()
    conn.close()

    return {
        "status": "deleted",
        "room_id": room_id,
        "devices_preserved_and_unassigned": devices_count
    }

@app.put("/rooms/{room_id}")
def update_room(room_id: int, data: dict):
    room_name = data.get("room_name", "").strip()
    polygon_points = data.get("polygon_points", None)

    if not room_name:
        raise HTTPException(status_code=400, detail="room_name required")

    conn = db()

    room = conn.execute("""
        SELECT *
        FROM rooms
        WHERE id = ?
    """, (room_id,)).fetchone()

    if not room:
        conn.close()
        raise HTTPException(status_code=404, detail="Room not found")

    if polygon_points is not None:
        if not isinstance(polygon_points, list) or len(polygon_points) < 3:
            conn.close()
            raise HTTPException(
                status_code=400,
                detail="polygon_points must contain at least 3 points"
            )

        x_values = [p["x"] for p in polygon_points]
        y_values = [p["y"] for p in polygon_points]

        center_x = int(sum(x_values) / len(x_values))
        center_y = int(sum(y_values) / len(y_values))

        conn.execute("""
            UPDATE rooms
            SET room_name = ?,
                polygon_points = ?,
                x = ?,
                y = ?
            WHERE id = ?
        """, (
            room_name,
            json.dumps(polygon_points),
            center_x,
            center_y,
            room_id,
        ))

    else:
        conn.execute("""
            UPDATE rooms
            SET room_name = ?
            WHERE id = ?
        """, (
            room_name,
            room_id,
        ))

    conn.commit()
    conn.close()

    return {
        "status": "updated",
        "room_id": room_id,
        "room_name": room_name,
    }

@app.get("/floors/{floor_id}/rooms")
def get_floor_rooms(floor_id: int):

    conn = db()

    floor = conn.execute("""
        SELECT *
        FROM floors
        WHERE id = ?
    """, (floor_id,)).fetchone()

    if not floor:
        conn.close()
        raise HTTPException(
            status_code=404,
            detail="Floor not found"
        )

    rooms = conn.execute("""
        SELECT *
        FROM rooms
        WHERE floor_id = ?
        ORDER BY room_name
    """, (floor_id,)).fetchall()

    result = []

    for room in rooms:

        room_obj = dict(room)

        try:
            room_obj["polygon_points"] = (
                json.loads(room_obj["polygon_points"])
                if room_obj["polygon_points"]
                else []
            )
        except:
            room_obj["polygon_points"] = []

        result.append(room_obj)

    conn.close()

    return result
    
